// ------------------------------------------------------------------------------------------------- azar
// xorshift (sin <random>: igual en el PC y en la consola)
struct Azar {
	uint32_t s{ 0x9E3779B9u };
	explicit Azar(uint32_t semilla = 0x9E3779B9u) : s(semilla ? semilla : 1u) {}
	uint32_t siguiente()
	{
		s ^= s << 13;
		s ^= s >> 17;
		s ^= s << 5;
		return s;
	}
	int hasta(int n) { return n > 0 ? (int)(siguiente() % (uint32_t)n) : 0; }
	float uno() { return (float)(siguiente() >> 8) * (1.0f / 16777216.0f); }   // [0, 1)
	float entre(float a, float b) { return a + (b - a) * uno(); }
	float normal()   // ~N(0, 1) (suma de 4 uniformes)
	{
		return (uno() + uno() + uno() + uno() - 2.0f) * 1.732f;
	}
};
template <class T> void barajar(std::vector<T>& v, Azar& a)
{
	for (int i = (int)v.size() - 1; i > 0; i--) std::swap(v[i], v[a.hasta(i + 1)]);
}
inline uint32_t mezclar(uint32_t a, uint32_t b) { return (a ^ (b + 0x9E3779B9u + (a << 6) + (a >> 2))) | 1u; }

inline std::vector<std::string> partir(const std::string& linea, char sep)
{
	std::vector<std::string> c;
	size_t a = 0, b;
	while ((b = linea.find(sep, a)) != std::string::npos) {
		c.push_back(linea.substr(a, b - a));
		a = b + 1;
	}
	c.push_back(linea.substr(a));
	return c;
}
inline std::vector<std::string> palabras(const std::string& s)
{
	std::vector<std::string> r;
	for (const std::string& p : partir(s, ' '))
		if (!p.empty()) r.push_back(p);
	return r;
}

// ------------------------------------------------------------------------------------------------- personalidades
// Pesos 0..1 salvo umbral (puntos). ritmo: s base de pensar. Las claves son las de rivales.txt
struct Personalidad {
	const char* clave;
	float agresividad;   // ganas de atacar y de invocar en ataque
	float cautela;       // respeto a las cartas boca abajo del rival y a quedar expuesto
	float farol;         // colocar magias/trampas (y monstruos) boca abajo aunque no hagan nada
	float riesgo;        // aceptar intercambios 1x1 y ataques dudosos
	float paciencia;     // guardar cartas, preparar sacrificios, esperar el momento
	float umbral;        // ganancia minima para atacar (el "dial 1" del juego original: 0 = rechaza el 1x1)
	float ritmo;         // s base de cada jugada
};
