constexpr int NUM_PERSONALIDADES = (int)(sizeof(PERSONALIDADES) / sizeof(PERSONALIDADES[0]));
inline const Personalidad& personalidadPorClave(const std::string& k)
{
	for (const Personalidad& p : PERSONALIDADES)
		if (k == p.clave) return p;
	return PERSONALIDADES[0];
}

