class Cerebro;
struct GanchosLog {
	void (*suceso)(const Duelo&, const Suceso&){ nullptr };
	void (*jugada)(const Duelo&, const Jugada&){ nullptr };
	void (*candidatas)(const Duelo&, const std::vector<Jugada>&){ nullptr };
	void (*decision)(const Duelo&, const Jugada&, const Cerebro&){ nullptr };
};
inline GanchosLog ganchosLog;

class Duelo {
public:
	const Base* base{ nullptr };
	std::array<Lado, 2> l{};
	int turno{ 0 }, activo{ 0 }, ganador{ -1 };   // ganador -1 en juego, 0/1, 2 empate
	Fase fase{ F_ROBO };
	std::vector<Suceso> sucesos;
	std::function<void(const Suceso&)> alAplicar;   // gancho del registro (el motor de efectos va por dentro: motorSuceso)
	bool log{ false };
	EstadoEfectos ef;   // rama classic-efectos: cadena, ventana de respuesta, pregunta pendiente, combate en curso
	bool efectos{ true };   // false: el duelo de antes, sin efectos de cartas (comparar en las pruebas)
	// rama classic-ciclos: Opciones > "Preguntar antes de activar" = Siempre: a ese lado se le ofrece cada ventana de
	// respuesta aunque no tenga nada que activar (solo "No activar"). Lo pone el juego para el jugador (lado 0)
	std::array<bool, 2> preguntarSiempre{};
	// rama classic-en-linea: el lado del que mira la pantalla (0 contra la IA; en el duelo en red, el propio: el
	// invitado es el lado 1). Solo decide a quien se le muestran las cartas que mira un efecto (S_REVELA de Big Eye,
	// Ancient Telescope...); no cambia el estado (hashEstado no lo lleva) ni gasta azar
	int ladoVista{ 0 };
	std::string ultimoDefensor;   // (el defensor del calculo en curso: Amazoness Swords Woman)

	explicit Duelo(const Base* b = nullptr) : base(b) {}

	const Carta* carta(const std::string& id) const { return base ? base->carta(id) : nullptr; }
	int atk(const std::string& id) const
	{
		const Carta* c = carta(id);
		return c ? c->atk : 0;
	}
	int def(const std::string& id) const
	{
		const Carta* c = carta(id);
		return c ? c->def : 0;
	}
	int nivel(const std::string& id) const
	{
		const Carta* c = carta(id);
		return c ? c->nivel : 0;
	}
	// ATK/DEF de verdad de un monstruo del campo (con equipos, campos y efectos: Duelo::recalcular)
	int atkM(const Monstruo& m) const { return m.vacia() ? 0 : m.atkEf; }
	int defM(const Monstruo& m) const { return m.vacia() ? 0 : m.defEf; }
	static int tributosPara(int nivel) { return nivel >= 7 ? 2 : nivel >= 5 ? 1 : 0; }
	// los Dioses Egipcios (cartas firma, atributo DIVINIDAD): 3 sacrificios y no se pueden colocar boca abajo
	static bool divina(const Carta* c) { return c && (c->atributo == "DIVINIDAD" || c->atributo == "DIVINE" || c->raza == "Bestia Divina"); }
	static int tributosPara(const Carta* c) { return !c ? 0 : divina(c) ? 3 : tributosPara(c->nivel); }
	// cuanto vale como sacrificio para invocar "c": 2 los de doble sacrificio de su atributo (Kaiser Sea Horse...)
	static int valorTributo(const std::string& id, const Carta* c)
	{
		if (!c || divina(c)) return 1;
		static const char* const DOBLES[][2] = { { "kaiser_sea_horse", "LUZ" }, { "whirlwind_prodigy", "VIENTO" }, { "flame_ruler", "FUEGO" },
			                                     { "double_coston", "OSCURIDAD" }, { "unshaven_angler", "AGUA" }, { "the_trojan_horse", "TIERRA" } };
		for (const auto& dbl : DOBLES)
			if (id == dbl[0] && c->atributo == dbl[1]) return 2;
		return 1;
	}

	// quien tiene que decidir ahora: el que tiene una pregunta pendiente (responder o elegir) o el del turno
	int decide() const { return ef.preg.tipo != P_NADA ? ef.preg.lado : activo; }
	// hay una cadena, una pregunta o un combate a medias: el turno no sigue hasta que se resuelva
	bool ocupado() const { return ef.preg.tipo != P_NADA || !ef.cadena.empty() || ef.resolviendo || ef.pendiente != PEND_NADA; }

	// mazos ya armados; quien empieza sale de la semilla. barajarMazos = false (rama classic-red-base, duelo en linea):
	// los mazos ya vienen barajados por su duenno (barajado con compromiso, red/compromiso.h)
	void empezar(const std::vector<std::string>& principal0, const std::vector<std::string>& fusion0, const std::vector<std::string>& principal1,
	             const std::vector<std::string>& fusion1, uint32_t semilla, int empieza = -1, bool barajarMazos = true)
	{
		Azar a(semilla);
		a.siguiente();
		l = {};
		ef = EstadoEfectos{};
		ef.azar = Azar(mezclar(semilla, 0xEFu));
		l[0].mazo = principal0;
		l[0].extra = fusion0;
		l[1].mazo = principal1;
		l[1].extra = fusion1;
		for (Lado& x : l) {
			if (barajarMazos) barajar(x.mazo, a);
			for (int k = 0; k < MANO_INICIAL; k++) robar(x);
		}
		activo = empieza >= 0 ? empieza : a.hasta(2);
		turno = 0;
		ganador = -1;
		sucesos.clear();
		empezarTurno();
	}

	// el turno de "activo" empieza: se roba (la fase de robo), la de espera (efectos) y pasa a la principal 1
	void empezarTurno()
	{
		turno++;
		Lado& x = l[(size_t)activo];
		x.invocoNormal = false;
		for (Monstruo& m : x.m) m.llegoEsteTurno = m.cambioPosicion = m.ataco = false;
		ef.batallaTerminada = false;
		ef.sinDannoBatalla = {};
		ef.sinDestruirBatalla = {};
		ef.porTurno = {};
		ef.destruidosBatalla = {};
		ef.destruidosCampo = {};
		ef.desterradosCampo = {};
		ef.dannoPend = {};   // (rama classic-reglas-oficiales: la ventana del danno no pasa de un turno a otro)
		ef.dannoPendBatalla = {};
		for (Lado& lx : l)
			for (Monstruo& mx : lx.m) {
				mx.directoTurno = false;
				mx.ataquesExtra = 0;
				if (mx.id == "asura_priest" || mx.id == "mermaid_knight" || mx.id == "ultimate_tyranno" || mx.id == "berserk_dragon" ||
				    mx.id == "armed_samurai_ben_kei")
					mx.contadores = 0;
			}
		suceso({ S_TURNO, activo, -1, -1, turno });
		fase = F_ROBO;
		if (efectos && ef.m2DiosaSalto) {   // (Mischief of the Time Goddess: sin robo, espera ni principal 1)
			ef.m2DiosaSalto = false;
			irFase(F_BATALLA);
			motorVentana(*this, Ventana{ V_INICIO_BATALLA, activo, -1, 0, {} });
			return;
		}
		if (x.mazo.empty()) {
			terminar(1 - activo);
			return;
		}
		if (efectos) motorAntesRobo(*this);   // (Hino-Kagu-Tsuchi)
		if (efectos && ef.saltaRobo[(size_t)activo] > 0)   // (Offerings to the Doomed, Reckless Greed: sin robo)
			ef.saltaRobo[(size_t)activo]--;
		else {
			robar(x);
			suceso({ S_ROBO, activo, -1, -1, (int)x.mano.size() - 1, false, x.mano.back() });
		}
		if (efectos) motorFaseEspera(*this);
		if (ganador >= 0) return;
		// (rama classic-motor2: la ventana de la fase de espera, si alguien tiene una carta de ese momento; al cerrarse sigue
		// en continuarTurno)
		if (efectos && ef.disparos.empty() && esperaRelevante()) {
			motorVentana(*this, Ventana{ V_ESPERA, activo, -1, 0, {} }, PEND_ESPERA);
			return;
		}
		continuarTurno();
	}
	bool esperaRelevante() const;   // (rama classic-motor2: mas abajo)
	bool sinFaseBatallaM2() const;  // (rama classic-motor2: D.D. Borderline)
	void terminarBatalla();          // (rama classic-motor2: tras la ventana del final de la batalla)
	// (rama classic-motor2) la repeticion del ataque: cambio el numero de monstruos del rival y el ataque no sigue; el
	// atacante puede volver a declarar un ataque (o no)
	void repetirAtaque(Monstruo& a)
	{
		if (ef.m2Repeticion == 2) a.ataquesExtra++;
		else a.ataco = false;
		ef.m2Repeticion = 0;
	}
	// (rama classic-reglas-oficiales) los objetivos posibles de la repeticion del ataque del monstruo (lado, za): primero el
	// objetivo de antes (uidAntes) si sigue, luego los demas; {otro, EN_MONSTRUO, -1} = ataque directo
	std::vector<Lugar> objetivosRepeticion(int lado, int za, int uidAntes) const
	{
		std::vector<Lugar> r;
		const int otro = 1 - lado;
		const Lado& y = l[(size_t)otro];
		for (int o = 0; o < ZONAS; o++)
			if (!y.m[(size_t)o].vacia() && y.m[(size_t)o].uid == uidAntes && uidAntes != 0 && motorAtacable(*this, otro, o)) r.push_back({ otro, EN_MONSTRUO, o });
		for (int o = 0; o < ZONAS; o++)
			if (!y.m[(size_t)o].vacia() && (y.m[(size_t)o].uid != uidAntes || uidAntes == 0) && motorAtacable(*this, otro, o)) r.push_back({ otro, EN_MONSTRUO, o });
		if ((y.monstruos() == 0 || motorAtaqueDirecto(*this, lado, za)) && motorPuedeDirecto(*this, lado, za)) r.push_back({ otro, EN_MONSTRUO, -1 });
		return r;
	}
	// (rama classic-reglas-oficiales) la repeticion del ataque: pregunta al atacante (otro objetivo, el mismo o no atacar)
	void pedirRepeticion(Monstruo& a, int lado, int za, int uidAntes)
	{
		const std::vector<Lugar> cands = objetivosRepeticion(lado, za, uidAntes);
		if (cands.empty() || ganador >= 0) {   // (no puede atacar a nada: no ataca; puede volver a declarar si cambia el campo)
			repetirAtaque(a);
			return;
		}
		ef.repeticion = EstadoEfectos::Repeticion{};
		ef.repeticion.hay = true;
		ef.repeticion.lado = lado;
		ef.repeticion.uidA = a.uid;
		ef.repeticion.gasto = ef.m2Repeticion;
		Pregunta p;
		p.tipo = P_ELEGIR;
		p.lado = lado;
		p.carta = a.id;
		p.texto = "ef.elegir.repeticion";
		p.cands = cands;
		p.faltan = 1;
		p.opcional = true;
		ef.preg = p;
	}
	// (rama classic-reglas-oficiales) la respuesta a la repeticion: k = indice del objetivo, -1 = no atacar
	bool responderRepeticion(int k)
	{
		const EstadoEfectos::Repeticion rp = ef.repeticion;
		const std::vector<Lugar> cands = ef.preg.cands;
		if (k >= (int)cands.size()) return false;
		ef.repeticion = EstadoEfectos::Repeticion{};
		ef.preg = Pregunta{};
		int la = -1, za = -1;
		Monstruo* a = porUid(rp.uidA, &la, &za);
		ef.m2Repeticion = rp.gasto;
		if (!a || la != rp.lado) return true;
		if (k < 0) {   // no ataca: el monstruo puede volver a atacar en esta fase (la regla de la repeticion)
			repetirAtaque(*a);
			return true;
		}
		const Lugar g = cands[(size_t)k];
		const Lado& y = l[(size_t)(1 - rp.lado)];
		ef.ataque = EstadoEfectos::Ataque{};
		ef.ataque.hay = true;
		ef.ataque.lado = rp.lado;
		ef.ataque.zona = za;
		ef.ataque.objetivo = g.i;
		ef.ataque.uidA = a->uid;
		ef.ataque.uidO = g.i >= 0 ? y.m[(size_t)g.i].uid : 0;
		ef.ataque.nRival = y.monstruos();
		motorAtaqueDeclarado(*this);   // (Dreamsprite, Maiden with Eyes of Blue: una declaracion nueva)
		suceso({ S_ATAQUE, rp.lado, za, ef.ataque.objetivo, 1, false, a->id });   // (valor 1: repeticion)
		motorVentana(*this, Ventana{ V_ATAQUE, rp.lado, za, a->uid, a->id }, PEND_BATALLA);
		return true;
	}
	// despues de la fase de espera: la principal 1 (o la batalla, con Timeater)
	void continuarTurno()
	{
		if (ganador >= 0) return;
		if (efectos && ef.sinMP1[(size_t)activo] == turno) {   // (Timeater: sin fase principal 1)
			irFase(F_BATALLA);
			motorVentana(*this, Ventana{ V_INICIO_BATALLA, activo, -1, 0, {} });
		} else
			irFase(F_PRINCIPAL1);
		if (efectos && ganador < 0 && !ef.disparos.empty() && ef.preg.tipo == P_NADA && ef.cadena.empty())   // (mantenimientos y usos de la espera)
			motorVentana(*this, Ventana{ V_DISPARO, activo, -1, 0, {} });
	}

	// ---- reglas: se puede?
	bool puedeInvocarNormal(int lado, int k, const std::vector<int>& tributos) const
	{
		const Lado& x = l[(size_t)lado];
		if (x.invocoNormal || !principal() || ocupado() || k < 0 || k >= (int)x.mano.size()) return false;
		const Carta* c = carta(x.mano[(size_t)k]);
		if (!c || !(c->clase == "normal" || c->clase == "efecto") || c->noInvocable) return false;
		if (efectos && !motorPuedeInvocar(*this, lado, c->id, (int)tributos.size())) return false;   // (Guardianes, Kaiser Colosseum)
		// (rama classic-efectos: un monstruo de "doble sacrificio" cuenta 2 para su atributo; sin sacrificios de sobra)
		int nec = efectos ? motorTributos(*this, lado, c) : tributosPara(c);   // (Cost Down)
		if (efectos && !motorPuedePagarMano(*this, lado, 1)) return false;   // (Chain Energy)
		if (efectos && c->id == "behemoth_the_king_of_all_animals" && tributos.size() == 1) nec = 1;   // (Behemoth: con 1 sacrificio)
		if (efectos && c->id == "fusilier_dragon_the_dual_mode_beast" && tributos.empty()) nec = 0;   // (Fusilier Dragon: sin sacrificios, la mitad)
		if (efectos && c->id == "swift_gaia_the_fierce_knight" && tributos.empty() && x.mano.size() == 1) nec = 0;   // (Swift Gaia: unica carta de la mano)
		if (efectos && !tributos.empty() && motorSinSacrificios(*this)) return false;   // (Mask of Restrict)
		int valor = 0;
		for (int t : tributos)
			if (t >= 0 && t < ZONAS) valor += valorTributo(x.m[(size_t)t].id, c);
		const bool tres = efectos && (c->id == "moisture_creature" || c->id == "gilford_the_lightning") && tributos.size() == 3;   // (Moisture Creature: con 3 sacrificios)
		if (((int)tributos.size() > nec && !tres) || valor < nec || (nec == 0 && !tributos.empty())) return false;
		for (size_t a = 0; a < tributos.size(); a++) {
			const int t = tributos[a];
			if (t < 0 || t >= ZONAS || x.m[(size_t)t].vacia()) return false;
			for (size_t b = 0; b < a; b++)
				if (tributos[b] == t) return false;   // (el mismo monstruo dos veces)
		}
		return x.libre() >= 0 || !tributos.empty();
	}
	bool principal() const { return fase == F_PRINCIPAL1 || fase == F_PRINCIPAL2; }
	bool puedeAtacar(int lado, int z) const
	{
		if (fase != F_BATALLA || turno <= 1 || lado != activo || z < 0 || z >= ZONAS || ocupado() || ef.batallaTerminada) return false;   // sin batalla en el primer turno
		const Monstruo& m = l[(size_t)lado].m[(size_t)z];
		if (m.vacia() || m.bocaAbajo || m.defensa || m.ataco) return false;
		return !efectos || (motorPuedeAtacar(*this, lado, z) && motorHayObjetivo(*this, lado, z));
	}

	// ---- aplicar una jugada del lado que decide (devuelve si se pudo)
	bool aplicar(const Jugada& j)
	{
		if (ganador >= 0) return false;
		if (ganchosLog.jugada) ganchosLog.jugada(*this, j);   // (bitacora: duelo_log.h)
		if (j.tipo == J_ACTIVAR || j.tipo == J_PASAR || j.tipo == J_ELEGIR) {
			if (!efectos) return false;
			const bool ok = motorJugada(*this, j);
			recalcular();
			if (ok && !ocupado()) abrirVentanaDanno(*this);   // (rama classic-reglas-oficiales)
			return ok;
		}
		if (ocupado()) return false;   // primero la pregunta / la cadena
		const bool ok = aplicarBasica(j);
		recalcular();
		if (ok && efectos && !ocupado()) abrirVentanaDanno(*this);   // (rama classic-reglas-oficiales: el danno de la jugada)
		return ok;
	}

	// los materiales (con repeticion) cubren la receta? (cada carta cuenta una vez)
	static bool cubre(std::vector<std::string> hay, const std::vector<std::string>& receta)
	{
		for (const std::string& r : receta) {
			auto it = std::find(hay.begin(), hay.end(), r);
			if (it == hay.end()) return false;
			hay.erase(it);
		}
		return true;
	}

	// (rama classic-efectos) un sustituto de fusion hace de uno de los materiales; los demas, los de la receta
	static bool cubreSustituto(std::vector<std::string> hay, const std::vector<std::string>& receta)
	{
		for (size_t s = 0; s < hay.size(); s++) {
			if (!esSustitutoFusion(hay[s])) continue;
			std::vector<std::string> resto = hay;
			resto.erase(resto.begin() + (long)s);
			for (size_t k = 0; k < receta.size(); k++) {
				std::vector<std::string> r2 = receta;
				r2.erase(r2.begin() + (long)k);
				if (cubre(resto, r2)) return true;
			}
		}
		return false;
	}

	// ================================================================ primitivas (las usa el motor de efectos)
	void suceso(const Suceso& s)
	{
		if (log)
			fprintf(stderr, "[duelo] t%d %s lado %d zona %d/%d valor %d %s\n", turno, NOMBRE_SUCESO[s.tipo], s.lado, s.zona, s.zona2, s.valor,
			        s.carta.c_str());
		sucesos.push_back(s);
		if (ganchosLog.suceso) ganchosLog.suceso(*this, s);   // (bitacora: duelo_log.h)
		if (efectos) motorSuceso(*this, s);
		if (alAplicar) alAplicar(s);
	}
	void recalcular()
	{
		if (efectos) {
			motorRecalcular(*this);
			return;
		}
		for (Lado& x : l)
			for (Monstruo& m : x.m)
				if (!m.vacia()) m.atkEf = atk(m.id), m.defEf = def(m.id);
	}
	int nuevoUid() { return ++ef.uid; }
	// el monstruo con este uid (nullptr si ya no esta en el campo)
	Monstruo* porUid(int uid, int* lado = nullptr, int* zona = nullptr)
	{
		if (uid <= 0) return nullptr;
		for (int a = 0; a < 2; a++)
			for (int z = 0; z < ZONAS; z++)
				if (l[(size_t)a].m[(size_t)z].uid == uid && !l[(size_t)a].m[(size_t)z].vacia()) {
					if (lado) *lado = a;
					if (zona) *zona = z;
					return &l[(size_t)a].m[(size_t)z];
				}
		return nullptr;
	}
	const Monstruo* porUid(int uid, int* lado = nullptr, int* zona = nullptr) const { return const_cast<Duelo*>(this)->porUid(uid, lado, zona); }
	MagiaTrampa* mtEn(const Lugar& g)
	{
		if (g.lado < 0 || g.lado > 1) return nullptr;
		if (g.donde == EN_CAMPO) return &l[(size_t)g.lado].campo;
		if (g.donde == EN_MT && g.i >= 0 && g.i < ZONAS) return &l[(size_t)g.lado].mt[(size_t)g.i];
		return nullptr;
	}
	const MagiaTrampa* mtEn(const Lugar& g) const { return const_cast<Duelo*>(this)->mtEn(g); }

	// roba una carta por un efecto (sin cartas en el mazo: pierde)
	bool robarEfecto(int lado)
	{
		if (efectos && motorProtegeRobo(*this, lado)) return false;   // (Protector of the Sanctuary)
		Lado& x = l[(size_t)lado];
		if (x.mazo.empty()) {
			terminar(1 - lado);
			return false;
		}
		robar(x);
		suceso({ S_ROBO, lado, -1, -1, (int)x.mano.size() - 1, false, x.mano.back() });
		if (efectos && ef.mukoUid > 0 && ef.resolviendo && !ef.cadena.empty() && ef.cadena.back().uidFuente == ef.mukoUid)
			descartar(lado, (int)x.mano.size() - 1);   // (Muko)
		return true;
	}
	// un monstruo del campo se va al cementerio de su duenno (destruido, sacrificado o enviado); sus equipos con el
	void alCementerio(int lado, int z, bool porBatalla = false)
	{
		Monstruo& m = l[(size_t)lado].m[(size_t)z];
		if (m.vacia()) return;
		const Monstruo antes = m;
		const int duenno = m.duenno >= 0 ? m.duenno : lado;
		m = Monstruo{};
		ef.negandoBatalla = efectos && porBatalla && motorNegadoEnBatalla(*this, lado, antes);   // (Ha Des...)
		{
			Suceso sc{ S_AL_CEMENTERIO, lado, z, -1, porBatalla ? 1 : 0, false, antes.id };
			sc.destruida = !porBatalla && (ef.destruyendo > 0 || !ef.sacrificando);   // (rama classic-ps5-efectos3: solo presentacion)
			suceso(sc);
		}
		ef.negandoBatalla = false;
		if (efectos && !antes.token && !antes.bocaAbajo && antes.id == "dark_magician_of_chaos")
			l[(size_t)duenno].desterrados.push_back(antes.id);   // (Dark Magician of Chaos: se destierra)
		else if (!antes.token && efectos && porBatalla && motorGraveProtector(*this)) {   // (Grave Protector: al mazo)
			l[(size_t)duenno].mazo.push_back(antes.id);
			barajar(l[(size_t)duenno].mazo, ef.azar);
		} else if (!antes.token && efectos && motorBanisher(*this))
			l[(size_t)duenno].desterrados.push_back(antes.id);   // (Banisher of the Light)
		else if (!antes.token)
			l[(size_t)duenno].cementerio.push_back(antes.id);   // (una ficha desaparece)
		if (efectos && antes.id == "balloon_lizard" && antes.contadores > 0 && !antes.bocaAbajo) danno(1 - lado, 400 * antes.contadores);
		if (!antes.token) {
			ef.destruidosCampo[(size_t)duenno].push_back(antes.id);
			if (porBatalla) ef.destruidosBatalla[(size_t)duenno].push_back(antes.id);
		}
		salioMonstruo(antes);
	}
	// sale del campo sin ir al cementerio: a la mano (de su duenno) o desterrado
	void sacarMonstruo(int lado, int z, bool aLaMano)
	{
		Monstruo& m = l[(size_t)lado].m[(size_t)z];
		if (m.vacia()) return;
		const Monstruo antes = m;
		const int duenno = m.duenno >= 0 ? m.duenno : lado;
		m = Monstruo{};
		const Carta* c = carta(antes.id);
		if (antes.token) {
			suceso({ S_DESTERRADO, lado, z, -1, 2, false, antes.id });   // (la ficha desaparece)
		} else if (aLaMano && c && c->clase == "fusion") {   // una fusion "a la mano" vuelve al mazo de fusion
			l[(size_t)duenno].extra.push_back(antes.id);
			suceso({ S_A_LA_MANO, lado, z, -1, 1, false, antes.id });
		} else if (aLaMano) {
			l[(size_t)duenno].mano.push_back(antes.id);
			suceso({ S_A_LA_MANO, lado, z, -1, 0, false, antes.id });
		} else {
			l[(size_t)duenno].desterrados.push_back(antes.id);
			if (!antes.bocaAbajo && duenno == lado) ef.desterradosCampo[(size_t)lado].push_back(antes.id);
			suceso({ S_DESTERRADO, lado, z, -1, 0, false, antes.id });
		}
		salioMonstruo(antes);
	}
	// una magia/trampa (zona 0..4 o ZONA_CAMPO) va al cementerio de su lado
	void mtAlCementerio(int lado, int z)
	{
		MagiaTrampa& c = z == ZONA_CAMPO ? l[(size_t)lado].campo : l[(size_t)lado].mt[(size_t)z];
		if (c.vacia()) return;
		const MagiaTrampa antes = c;
		c = MagiaTrampa{};
		(efectos && motorBanisher(*this) ? l[(size_t)lado].desterrados : l[(size_t)lado].cementerio).push_back(antes.id);   // (Banisher of the Light)
		{
			Suceso sc{ S_AL_CEMENTERIO, lado, z, -1, 0, true, antes.id };   // (z: 0..4 o ZONA_CAMPO)
			sc.destruida = ef.destruyendo > 0;   // (rama classic-ps5-efectos3: solo presentacion; la que resuelve y se va no)
			suceso(sc);
		}
		if (efectos) motorColocadaDestruida(*this, lado, antes);   // (Kozaky's Self-Destruct Button...)
		if (efectos) motorSaleMT(*this, lado, antes);
	}
	void aCementerio(int lado, const std::string& id)
	{
		(efectos && motorBanisher(*this) ? l[(size_t)lado].desterrados : l[(size_t)lado].cementerio).push_back(id);   // (Banisher of the Light)
		suceso({ S_AL_CEMENTERIO, lado, -1, -1, 0, false, id });
	}
	// descarta la carta k de la mano
	void descartar(int lado, int k)
	{
		Lado& x = l[(size_t)lado];
		if (k < 0 || k >= (int)x.mano.size()) return;
		const std::string id = x.mano[(size_t)k];
		x.mano.erase(x.mano.begin() + k);
		(efectos && motorBanisher(*this) ? x.desterrados : x.cementerio).push_back(id);   // (Banisher of the Light)
		suceso({ S_DESCARTA, lado, -1, -1, k, false, id });
	}
	void danno(int lado, int n)
	{
		if (n <= 0 || (efectos && ef.sinDannoHasta[(size_t)lado] >= turno)) return;
		Lado& x = l[(size_t)lado];
		x.lp = std::max(0, x.lp - n);
		suceso({ S_DANNO, lado, -1, -1, n });
		if (x.lp <= 0) terminar(1 - lado);
	}
	// (rama classic-reglas-oficiales) danno de batalla: lo anota para la ventana del danno (Inferno Tempest: 3000+ de un ataque)
	void dannoDeBatalla(int lado, int n)
	{
		const int antes = l[(size_t)lado].lp;
		danno(lado, n);
		if (efectos && l[(size_t)lado].lp < antes) ef.dannoPendBatalla[(size_t)lado] = std::max(ef.dannoPendBatalla[(size_t)lado], n);
	}
	void ganarLP(int lado, int n)
	{
		if (n <= 0) return;
		if (efectos && motorSimochi(*this, lado)) {   // (Bad Reaction to Simochi: la ganancia es danno)
			danno(lado, n);
			return;
		}
		l[(size_t)lado].lp += n;
		suceso({ S_LP, lado, -1, -1, n });
	}
	// invocacion especial (de donde sea: el que llama ya saco la carta de su lugar). Devuelve la zona o -1
	int invocarEspecial(int lado, const std::string& id, bool defensa, int duenno = -1, bool bocaAbajo = false)
	{
		const int z = l[(size_t)lado].libre();
		if (z < 0) return -1;
		if (efectos && !ef.m2Forzar && !motorPuedeInvocarM2(*this, lado, 2)) {   // (rama classic-motor2: The Last Warrior, Jowgen...)
			// (la carta ya salio de su lugar: va al cementerio de su duenno; las fichas de un monstruo con su nombre (Lekunga) no)
			const bool ficha = !ef.cadena.empty() && ef.cadena.back().carta == id && ef.cadena.back().deMonstruo;
			if (carta(id) && !ficha) l[(size_t)(duenno >= 0 ? duenno : lado)].cementerio.push_back(id);
			return -1;
		}
		ef.invocandoEspecial = true;
		ponerMonstruo(lado, z, id, bocaAbajo, defensa);
		ef.invocandoEspecial = false;
		Monstruo& m = l[(size_t)lado].m[(size_t)z];
		if (m.vacia()) return -1;   // (un efecto al llegar se lo llevo)
		m.duenno = duenno >= 0 && duenno != lado ? duenno : -1;
		m.especial = true;
		return z;
	}
	// el monstruo pasa al otro lado (Change of Heart, Snatch Steal) o vuelve. Devuelve la zona nueva o -1
	int cambiarControl(int lado, int z)
	{
		Monstruo& m = l[(size_t)lado].m[(size_t)z];
		const int otro = 1 - lado;
		const int nz = l[(size_t)otro].libre();
		if (m.vacia() || nz < 0) return -1;
		if (!m.bocaAbajo && m.id == "blindly_loyal_goblin") return -1;   // (su control no cambia)
		if (efectos && !m.bocaAbajo && !motorPuedeCambiarControl(*this, m)) return -1;
		Monstruo n = m;
		const int duenno = m.duenno >= 0 ? m.duenno : lado;
		n.duenno = duenno == otro ? -1 : duenno;
		n.llegoEsteTurno = true;   // (no cambia de posicion este turno; puede atacar)
		n.ataco = false;
		n.hastaFinTurno = false;
		m = Monstruo{};
		l[(size_t)otro].m[(size_t)nz] = n;
		suceso({ S_CONTROL, otro, nz, z, lado, false, n.id });
		return nz;
	}
	void voltearBocaArriba(int lado, int z, bool porAtaque)
	{
		Monstruo& m = l[(size_t)lado].m[(size_t)z];
		if (m.vacia() || !m.bocaAbajo) return;
		m.bocaAbajo = false;
		m.visto = true;
		m.vuelveFinTurno = carta(m.id) && carta(m.id)->subtipo == "espiritu";
		suceso({ S_VOLTEA, lado, z, -1, porAtaque ? 1 : 2, false, m.id });   // valor 1: por un ataque, 2: por un efecto
	}
	void terminar(int quien)
	{
		if (ganador >= 0) return;
		ganador = quien;
		suceso({ S_FIN, quien, -1, -1, turno });
	}
	void irFase(Fase f)
	{
		fase = f;
		suceso({ S_FASE, activo, -1, -1, (int)f });
	}
	void pasarTurno()
	{
		activo = 1 - activo;
		empezarTurno();
	}

	// el combate declarado (ef.ataque), despues de la ventana de respuesta: volteo, calculo, destruccion y danno
	// el paso de danno: el combate empieza (volteo del defensor) y se abre su ventana; despues, calculoDanno()
	void combate()
	{
		EstadoEfectos::Ataque at = ef.ataque;
		if (!at.hay || ganador >= 0) {
			ef.ataque = EstadoEfectos::Ataque{};
			return;
		}
		int la = -1, za = -1;
		Monstruo* a = porUid(at.uidA, &la, &za);
		if (!a || la != at.lado || a->bocaAbajo || a->defensa || at.negado) {   // el ataque no sigue (destruido, negado...)
			ef.ataque = EstadoEfectos::Ataque{};
			return;
		}
		const int yo = at.lado, otro = 1 - at.lado;
		Lado& y = l[(size_t)otro];
		recalcular();
		EstadoEfectos::Calculo c;
		c.hay = true;
		c.yo = yo;
		c.za = za;
		c.otro = otro;
		c.uidA = at.uidA;
		// (rama classic-reglas-oficiales) la repeticion del ataque: cambio el numero de monstruos del rival desde la declaracion
		// (Scapegoat...), aparecio un monstruo ante un ataque directo o el objetivo ya no esta: el atacante elige
		const bool cambio = efectos && !at.directo && at.nRival >= 0 && y.monstruos() != at.nRival;
		if (at.objetivo < 0) {
			if (cambio || (y.monstruos() > 0 && !at.directo && !(efectos && motorAtaqueDirecto(*this, yo, za)))) {
				ef.ataque = EstadoEfectos::Ataque{};
				if (efectos) pedirRepeticion(*a, yo, za, 0);
				return;
			}
			suceso({ S_COMBATE, yo, za, -1, 0, false, a->id });
		} else {
			int lo = -1, zo = -1;
			Monstruo* d = porUid(at.uidO, &lo, &zo);
			if (!d || lo != otro || cambio) {
				ef.ataque = EstadoEfectos::Ataque{};
				if (efectos) pedirRepeticion(*a, yo, za, d && lo == otro ? d->uid : 0);
				return;
			}
			suceso({ S_COMBATE, yo, za, zo, 0, false, a->id });
			c.zo = zo;
			c.uidO = d->uid;
			c.estabaBocaAbajo = d->bocaAbajo;
			c.idDef = d->id;
			if (d->bocaAbajo) voltearBocaArriba(otro, zo, true);   // se voltea (boca arriba en defensa)
			recalcular();
		}
		ef.calculo = c;
		if (efectos) motorVentana(*this, Ventana{ V_PASO_DANNO, yo, za, at.uidA, a->id }, PEND_CALCULO);   // (Shrink, Limiter Removal...)
		else calculoDanno();
	}

	// el calculo de danno del combate en curso (ef.calculo)
	void calculoDanno()
	{
		const EstadoEfectos::Calculo c = ef.calculo;
		ef.calculo = EstadoEfectos::Calculo{};
		ef.ataque = EstadoEfectos::Ataque{};
		struct Limpia {   // (Kuriboh: solo este combate)
			EstadoEfectos& e;
			~Limpia()
			{
				e.sinDannoCombate = {};
				e.combateLado = { { -1, -1 } };
				e.cruzado = 0;   // (Cross Counter: solo este combate)
			}
		} limpia{ ef };
		if (!c.hay || ganador >= 0) return;
		const int yo = c.yo, otro = c.otro;
		int la = -1, za = -1;
		Monstruo* a = porUid(c.uidA, &la, &za);
		if (!a || la != yo || a->bocaAbajo) return;
		recalcular();
		if (c.zo < 0) {
			if (!ef.sinDannoBatalla[(size_t)otro]) dannoBatalla(yo, za, a->atkEf);
			return;
		}
		int lo = -1, zo = -1;
		Monstruo* d = porUid(c.uidO, &lo, &zo);
		if (!d || lo != otro) return;
		const bool estabaBocaAbajo = c.estabaBocaAbajo;
		const std::string idDef = c.idDef;
		if (efectos) motorAntesCalculo(*this, yo, za, otro, zo, estabaBocaAbajo);   // (Reflect Bounder, Sasuke)
		recalcular();
		a = &l[(size_t)yo].m[(size_t)za];
		d = &l[(size_t)otro].m[(size_t)zo];
		if (a->vacia() || d->vacia() || ganador >= 0) return;
		const std::string idAtk = a->id;
		const int uidAtk = a->uid;
		ultimoDefensor = d->id;
		const int pa = a->atkEf;
		ef.combateId = { { a->id, d->id } };
		ef.combateLado = { { yo, otro } };
		ef.combateUid = { { a->uid, d->uid } };
		ef.combateDefensa = d->defensa;
		ef.combateBocaAbajo = estabaBocaAbajo;
		if (efectos && ef.luchaTurno == turno) ef.lucharon.insert(ef.lucharon.end(), { a->uid, d->uid });   // (After the Struggle)
		const bool negA = efectos && efectoNegado(*this, *a), negD = efectos && efectoNegado(*this, *d);   // (Skill Drain...)
		ef.negCombate = { { negA, negD } };   // (motorTrasCombate: los ids efectivos)
		bool noMuereA = ef.sinDestruirBatalla[(size_t)yo] || (efectos && !negA && (motorIndestructibleBatalla(a->id) || a->id == "rocket_warrior")) ||
		                (efectos && motorSinDestruirBatallaY(*this, yo, *a, *d)),
		     noMuereD = ef.sinDestruirBatalla[(size_t)otro] || (efectos && !negD && motorIndestructibleBatalla(d->id)) ||
		                (efectos && motorSinDestruirBatallaY(*this, otro, *d, *a)) ||
		                (efectos && !negD && d->id == "satellite_cannon" && nivelM(*this, *a) <= 7) ||
		                (efectos && !negD && d->id == "different_dimension_dragon" && a->atkEf <= 1900);
		if (efectos && !negA && a->id == "different_dimension_dragon" && d->atkEf <= 1900) noMuereA = true;
		if (efectos) {   // (lo que se destruye en su lugar: uniones, el equipo de Relinquished; Viser Des)
			const int pd0 = d->defensa ? d->defEf : d->atkEf;
			const bool pierdeD = d->defensa ? pa > pd0 : (pa > pd0 || (pa == pd0 && pa > 0));
			const bool pierdeA = !d->defensa && (pa < pd0 || (pa == pd0 && pa > 0));
			if (pierdeD && !noMuereD && motorSustitutoBatalla(*this, otro, zo)) noMuereD = true;
			if (pierdeA && !noMuereA && motorSustitutoBatalla(*this, yo, za)) noMuereA = true;
		}
		if (!d->defensa) {
			const int pd = d->atkEf;
			if (pa > pd) {
				if (!noMuereD) alCementerio(otro, zo, true);
				if (!ef.sinDannoBatalla[(size_t)otro]) dannoBatalla(yo, za, pa - pd);
			} else if (pa < pd) {
				if (!noMuereA) alCementerio(yo, za, true);
				if (!ef.sinDannoBatalla[(size_t)yo]) dannoAlAtacante(yo, idAtk, pd - pa);
			} else if (pa > 0) {
				if (!noMuereD) alCementerio(otro, zo, true);
				if (!noMuereA) alCementerio(yo, za, true);
			}
		} else {
			const int pd = d->defEf;
			if (pa > pd) {
				if (!noMuereD) alCementerio(otro, zo, true);
				if (efectos && ((motorPerfora(a->id) && !efectoNegado(*this, *a)) || motorPerforaLado(*this, yo, a->id)) && !ef.sinDannoBatalla[(size_t)otro]) dannoBatalla(yo, za, pa - pd);   // (perforante)
			} else if (pa < pd && !ef.sinDannoBatalla[(size_t)yo]) {
				// (rama classic-probador: Cross Counter: el danno de batalla al atacante es el doble)
				dannoAlAtacante(yo, idAtk, (pd - pa) * (efectos && c.uidA != 0 && ef.cruzado == c.uidA ? 2 : 1));
			}
		}
		ultimoDefensor.clear();
		if (efectos) motorTrasCombate(*this, yo, za, otro, zo, idDef, estabaBocaAbajo);
		if (efectos) motorTrasCombate2(*this, yo, za, otro, zo, idAtk, uidAtk, idDef);
	}

	// danno de batalla que recibe el atacante: Amazoness Swords Woman se lo pasa al rival
	void dannoAlAtacante(int yo, const std::string& atacante, int n)
	{
		if (efectos && ef.sinDannoCombate[(size_t)yo]) return;
		if (efectos && ef.sinDannoBatallaHasta[(size_t)yo] >= turno) return;   // (Ride of the Valkyries)
		if (efectos && (atacante == "amazoness_fighter" || atacante == "rocket_warrior" || atacante == "monk_fighter" || atacante == "dark_flare_knight")) return;   // (no recibes danno de sus combates)
		if (efectos && motorSinDannoBatalla(*this, yo, atacante)) return;   // (Emissary of the Oasis)
		if (efectos && motorSantuario(*this, atacante)) return;   // (The Sanctuary in the Sky: el Hada atacante)
		if (efectos && ultimoDefensor == "stone_statue_of_the_aztecs") n *= 2;
		dannoDeBatalla(efectos && atacante == "amazoness_swords_woman" ? 1 - yo : yo, n);
	}
	// danno de batalla que el atacante (lado, zona) le hace al otro: y lo que dispara (Airknight Parshath)
	void dannoBatalla(int lado, int z, int n)
	{
		const Monstruo m = l[(size_t)lado].m[(size_t)z];
		if (efectos && m.id == "gravekeeper_s_vassal" && !efectoNegado(*this, m)) {   // (rama classic-motor2: Gravekeeper's Vassal: su danno de batalla es danno de efecto)
			Eslabon e;
			e.carta = m.id;
			e.lado = lado;
			dannoEfecto(*this, e, 1 - lado, n);
			return;
		}
		if (efectos && ef.sinDannoCombate[(size_t)(1 - lado)]) return;   // (Kuriboh)
		if (efectos && ef.sinDannoBatallaHasta[(size_t)(1 - lado)] >= turno) return;   // (Ride of the Valkyries)
		const bool negM = efectos && efectoNegado(*this, l[(size_t)lado].m[(size_t)z]);   // (Skill Drain...)
		if (efectos && !negM && m.id == "piranha_army" && ultimoDefensor.empty()) n *= 2;   // (Piranha Army: directo, el doble)
		if (efectos && !negM && m.id == "susa_soldier") n /= 2;   // (Susa Soldier: la mitad)
		if (efectos)   // (Rod of the Mind's Eye: 1000)
			for (const MagiaTrampa& k : l[(size_t)lado].mt)
				if (!k.vacia() && !k.bocaAbajo && k.id == "rod_of_the_mind_s_eye" && k.eqUid == m.uid && m.uid > 0) n = 1000;
		if (efectos && motorMuroTornado(*this, 1 - lado)) return;   // (Tornado Wall)
		if (efectos && motorBarreraEspiritu(*this, 1 - lado)) return;   // (Spirit Barrier)
		if (efectos && (ultimoDefensor == "amazoness_fighter" || ultimoDefensor == "monk_fighter" || ultimoDefensor == "dark_flare_knight")) return;   // (Amazoness Fighter, Monk Fighter, Dark Flare Knight)
		if (efectos && !ultimoDefensor.empty() && motorSinDannoBatalla(*this, 1 - lado, ultimoDefensor)) return;   // (Emissary of the Oasis)
		if (efectos && motorSantuario(*this, ultimoDefensor)) return;   // (The Sanctuary in the Sky: el Hada defensora)
		if (efectos && ef.calculo.hay == false && ef.ataque.hay == false && ultimoDefensor == "amazoness_swords_woman") {
			dannoDeBatalla(lado, n);   // (Amazoness Swords Woman: lo recibe el que ataca)
			return;
		}
		dannoDeBatalla(1 - lado, n);
		ef.ultimoDannoBatalla = n;
		if (efectos && n > 0 && !m.vacia() && ganador < 0) motorDannoBatalla(*this, lado, z, m);
	}

private:
	static void robar(Lado& x)
	{
		if (x.mazo.empty()) return;
		x.mano.push_back(x.mazo.back());
		x.mazo.pop_back();
	}
	void ponerMonstruo(int lado, int z, const std::string& id, bool bocaAbajo, bool defensa)
	{
		Monstruo m;
		m.id = id;
		m.bocaAbajo = bocaAbajo;
		m.defensa = defensa;
		m.llegoEsteTurno = true;
		m.visto = !bocaAbajo;
		m.uid = nuevoUid();
		m.atkEf = atk(id);
		m.defEf = def(id);
		l[(size_t)lado].m[(size_t)z] = m;
		suceso({ bocaAbajo ? S_COLOCA : S_INVOCA, lado, z, -1, defensa ? 1 : 0, false, id });
	}
	// lo que pasa cuando un monstruo deja el campo: sus equipos (y Call of the Haunted) se destruyen
	void salioMonstruo(const Monstruo& m)
	{
		if (!efectos || m.uid <= 0) return;
		motorSaleMonstruo(*this, m);
		for (int a = 0; a < 2; a++) {
			for (int z = 0; z < ZONAS; z++) {
				const MagiaTrampa& c = l[(size_t)a].mt[(size_t)z];
				if (!c.vacia() && c.eqUid == m.uid) mtAlCementerio(a, z);
			}
		}
	}

	// las jugadas de siempre (invocar, colocar, voltear, atacar, fases...)
	bool aplicarBasica(const Jugada& j)
	{
		const int yo = activo;
		Lado& x = l[(size_t)yo];
		auto deLaMano = [&](std::vector<int> idx) {   // saca de la mano (de atras hacia adelante)
			std::vector<std::string> r;
			std::sort(idx.begin(), idx.end(), std::greater<int>());
			for (int k : idx) {
				r.push_back(x.mano[(size_t)k]);
				x.mano.erase(x.mano.begin() + k);
			}
			return r;
		};
		auto sacrificar = [&](const std::vector<int>& zonas) {
			ef.sacrificando = j.tipo == J_INVOCAR || j.tipo == J_COLOCAR;
			for (int t : zonas) alCementerio(yo, t);
			ef.sacrificando = false;
		};
		auto zonaLibre = [&](int pedida) { return pedida >= 0 && pedida < ZONAS && x.m[(size_t)pedida].vacia() && !x.bloqueada[(size_t)pedida] ? pedida : x.libre(); };
		auto invocado = [&](int z, int tipoVentana) {   // la ventana de respuesta a la invocacion (Trap Hole...)
			if (tipoVentana == V_INVOCACION_ESPECIAL) x.m[(size_t)z].especial = true;
			if (!efectos) return;
			// los Dioses Egipcios: al invocarse normal, nadie puede responder (solo sus propios efectos)
			if (divina(carta(x.m[(size_t)z].id)) && tipoVentana == V_INVOCACION_NORMAL) motorVentana(*this, Ventana{ V_DISPARO, yo, z, x.m[(size_t)z].uid, {} });
			else motorVentana(*this, Ventana{ tipoVentana, yo, z, x.m[(size_t)z].uid, x.m[(size_t)z].id });
		};

		switch (j.tipo) {
		case J_INVOCAR:
		case J_COLOCAR: {
			if (!puedeInvocarNormal(yo, j.mano, j.tributos)) return false;
			if (efectos && j.tipo == J_INVOCAR && !motorPuedeInvocarM2(*this, yo, 0)) return false;   // (rama classic-motor2: colocar si se puede)
			const std::string id = x.mano[(size_t)j.mano];
			if (j.tipo == J_COLOCAR && divina(carta(id))) return false;   // (un Dios no se puede colocar)
			if (efectos) {
				motorPagarMano(*this, yo, 1);   // (Chain Energy)
				ef.invocandoId = id;            // (Skull Knight #2)
				ef.atkSacrificio = 0;           // (Great Maju Garzett)
				ef.sumaSacrificio = 0;          // (Maju Garzett)
				for (int t2 : j.tributos)
					if (t2 >= 0 && t2 < ZONAS) {
						ef.atkSacrificio = std::max(ef.atkSacrificio, atk(x.m[(size_t)t2].id));
						ef.sumaSacrificio += std::max(0, atk(x.m[(size_t)t2].id));
					}
			}
			sacrificar(j.tributos);
			const int z = zonaLibre(j.zona);
			if (z < 0) return false;
			deLaMano({ j.mano });
			x.invocoNormal = true;
			const bool luz = efectos && j.tipo == J_COLOCAR && motorLuzIntervencion(*this);   // (Light of Intervention)
			ef.invocandoNormal = j.tipo == J_INVOCAR || luz;
			ef.conSacrificio = !j.tributos.empty();
			ef.nSacrificios = (int)j.tributos.size();
			ponerMonstruo(yo, z, id, j.tipo == J_COLOCAR && !luz, j.tipo == J_COLOCAR);
			if (efectos && id == "behemoth_the_king_of_all_animals" && j.tributos.size() == 1) x.m[(size_t)z].atkPerm = 2000 - atk(id);   // (Behemoth: ATK 2000)
			if (efectos && id == "fusilier_dragon_the_dual_mode_beast" && j.tributos.empty()) {   // (Fusilier Dragon sin sacrificios: ATK/DEF a la mitad)
				x.m[(size_t)z].atkPerm = -atk(id) / 2;
				x.m[(size_t)z].defPerm = -def(id) / 2;
			}
			if (luz) {
				ef.invocandoNormal = ef.conSacrificio = false;
				invocado(z, V_INVOCACION_NORMAL);
				return true;
			}
			ef.invocandoNormal = ef.conSacrificio = false;
			if (j.tipo == J_INVOCAR) {
				x.m[(size_t)z].vuelveFinTurno = carta(id) && carta(id)->subtipo == "espiritu";
				invocado(z, V_INVOCACION_NORMAL);
			} else if (efectos)   // (rama classic-motor2: el rival puede responder a que coloques: Shadow of Eyes)
				motorVentana(*this, Ventana{ V_COLOCADO, yo, z, x.m[(size_t)z].uid, {} });
			return true;
		}
		case J_TOON: {
			if (!principal() || j.mano < 0 || j.mano >= (int)x.mano.size() || !x.tieneBocaArriba("toon_world")) return false;
			const std::string id = x.mano[(size_t)j.mano];
			const Carta* c = carta(id);
			if (!c || c->subtipo != "toon" || (int)j.tributos.size() != (efectos ? motorTributos(*this, yo, c) : tributosPara(c))) return false;
			if (efectos && !motorPuedeInvocarM2(*this, yo, 2)) return false;   // (rama classic-motor2)
			if (efectos && !motorPuedePagarMano(*this, yo, 1)) return false;
			if (efectos) motorPagarMano(*this, yo, 1);   // (Chain Energy)
			sacrificar(j.tributos);
			const int z = zonaLibre(j.zona);
			if (z < 0) return false;
			deLaMano({ j.mano });
			ponerMonstruo(yo, z, id, false, false);
			invocado(z, V_INVOCACION_ESPECIAL);
			return true;
		}
		case J_VOLTEAR: {
			if (!principal() || j.zona < 0 || j.zona >= ZONAS) return false;
			Monstruo& m = x.m[(size_t)j.zona];
			if (m.vacia() || !m.bocaAbajo || m.llegoEsteTurno || m.cambioPosicion) return false;
			if (efectos && !motorPuedeInvocarM2(*this, yo, 1)) return false;   // (rama classic-motor2: The Last Warrior, Dark Magic Curtain)
			m.bocaAbajo = m.defensa = false;
			m.cambioPosicion = m.visto = true;
			m.vuelveFinTurno = carta(m.id) && carta(m.id)->subtipo == "espiritu";
			suceso({ S_VOLTEA, yo, j.zona, -1, 0, false, m.id });
			invocado(j.zona, V_VOLTEO);
			return true;
		}
		case J_POSICION: {
			if (!principal() || j.zona < 0 || j.zona >= ZONAS) return false;
			Monstruo& m = x.m[(size_t)j.zona];
			const bool goblin = efectos && goblinCambia(*this, yo, j.zona);   // (rama classic-motor2: Second Goblin equipado: 1 cambio por turno)
			if (m.vacia() || m.bocaAbajo || ((m.llegoEsteTurno || m.cambioPosicion) && !goblin)) return false;
			if (efectos && !goblin && motorPosicionFija(*this, yo, j.zona)) return false;   // (Gaap)
			if (goblin && (m.llegoEsteTurno || m.cambioPosicion || motorPosicionFija(*this, yo, j.zona))) ef.porTurno[(size_t)yo].push_back("second_goblin_pos");
			m.defensa = !m.defensa;
			m.cambioPosicion = true;
			suceso({ S_POSICION, yo, j.zona, -1, m.defensa ? 1 : 0, false, m.id });
			if (efectos && !ef.disparos.empty()) motorVentana(*this, Ventana{ V_DISPARO, yo, j.zona, m.uid, m.id });   // (Crass Clown)
			return true;
		}
		case J_COLOCAR_MT:
		case J_ACTIVAR_MT: {
			if (!principal() || j.mano < 0 || j.mano >= (int)x.mano.size()) return false;
			const Carta* c = carta(x.mano[(size_t)j.mano]);
			if (!c || !(c->magia || c->trampa)) return false;
			// J_ACTIVAR_MT: las magias continuas sin efecto propio en el motor (Toon World); las demas van por J_ACTIVAR
			if (j.tipo == J_ACTIVAR_MT && efectos && defCarta(c->id)) return false;
			if (efectos && !motorPuedePagarMano(*this, yo, 1)) return false;   // (Chain Energy)
			if (efectos && ondaFria(*this)) return false;   // (Cold Wave)
			// (rama classic-efectos) la magia de campo va a su zona; la que habia se va al cementerio
			if (efectos && c->subtipo == "magia_campo") {
				if (!x.campo.vacia()) mtAlCementerio(yo, ZONA_CAMPO);
				motorPagarMano(*this, yo, 1);
				const std::string id = deLaMano({ j.mano })[0];
				x.campo = MagiaTrampa{ id, j.tipo == J_COLOCAR_MT };
				x.campo.uid = nuevoUid();
				x.campo.turnoColocada = turno;
				suceso({ j.tipo == J_COLOCAR_MT ? S_COLOCA_MT : S_ACTIVA_MT, yo, ZONA_CAMPO, -1, 0, true, id });
				return true;
			}
			const int z = j.zona >= 0 && j.zona < ZONAS && x.mt[(size_t)j.zona].vacia() ? j.zona : x.libreMT();
			if (z < 0) return false;
			if (efectos) motorPagarMano(*this, yo, 1);
			const std::string id = deLaMano({ j.mano })[0];
			x.mt[(size_t)z] = MagiaTrampa{ id, j.tipo == J_COLOCAR_MT };
			x.mt[(size_t)z].uid = nuevoUid();
			x.mt[(size_t)z].turnoColocada = turno;
			suceso({ j.tipo == J_COLOCAR_MT ? S_COLOCA_MT : S_ACTIVA_MT, yo, z, -1, 0, true, id });
			return true;
		}
		case J_FUSION: {
			if (efectos && !motorPuedeInvocarM2(*this, yo, 2)) return false;   // (rama classic-motor2: The Last Warrior, Jowgen...)
			if (efectos && j.mano < 0 && fusionContacto(j.carta)) {   // (rama classic-motor2: X-Y-Z: sin Polymerization, desterrando las piezas)
				std::vector<int> mats;
				if (!principal() || !contactoPosible(*this, yo, j.carta, &mats)) return false;
				if (!j.tributos.empty()) {   // (las piezas elegidas: zonas de monstruo 0..4 o de magia/trampa 5..9, uniones equipadas)
					std::vector<std::string> ids;
					for (int t : j.tributos) {
						if (t < 0 || t >= 2 * ZONAS) return false;
						ids.push_back(t < ZONAS ? x.m[(size_t)t].id : x.mt[(size_t)(t - ZONAS)].id);
					}
					if (!cubre(ids, base->fusiones.at(j.carta)) || ids.size() != base->fusiones.at(j.carta).size()) return false;
					mats = j.tributos;
				}
				std::sort(mats.begin(), mats.end(), std::greater<int>());
				for (int t : mats) {   // (primero las uniones: si no, se irian al cementerio con el monstruo equipado)
					if (t < ZONAS) continue;
					MagiaTrampa& u = x.mt[(size_t)(t - ZONAS)];
					const std::string uid = u.id;
					u = MagiaTrampa{};
					x.desterrados.push_back(uid);
					suceso({ S_DESTERRADO, yo, t - ZONAS, -1, 3, true, uid });
				}
				for (int t : mats)
					if (t < ZONAS) sacarMonstruo(yo, t, false);
				const int z = zonaLibre(j.zona);
				auto ex = std::find(x.extra.begin(), x.extra.end(), j.carta);
				if (z < 0 || ex == x.extra.end()) return false;
				x.extra.erase(ex);
				ponerMonstruo(yo, z, j.carta, false, false);
				invocado(z, V_INVOCACION_ESPECIAL);
				return true;
			}
			if (!principal() || !base || j.mano < 0 || j.mano >= (int)x.mano.size() || x.mano[(size_t)j.mano] != "polymerization") return false;
			if (efectos && fusionContacto(j.carta)) return false;   // (rama classic-motor2: los X-Y-Z no usan Polymerization)
			if (efectos && !motorPuedeFusion(*this, yo)) return false;   // (The Seal of Orichalcos)
			auto it = base->fusiones.find(j.carta);
			auto ex = std::find(x.extra.begin(), x.extra.end(), j.carta);
			if (it == base->fusiones.end() || ex == x.extra.end()) return false;
			std::vector<std::string> mats;
			for (int k : j.manoExtra) {
				if (k < 0 || k >= (int)x.mano.size() || k == j.mano) return false;
				mats.push_back(x.mano[(size_t)k]);
			}
			for (int t : j.tributos) {
				if (t < 0 || t >= ZONAS || x.m[(size_t)t].vacia()) return false;
				mats.push_back(x.m[(size_t)t].id);
			}
			if (!cubre(mats, it->second) && !(efectos && !fusionSoloMateriales(j.carta) && cubreSustituto(mats, it->second))) return false;   // (sustitutos de fusion; motor2: no los de "solo con estos materiales")
			if (efectos && !motorPuedePagarMano(*this, yo, 1)) return false;   // (Chain Energy)
			if (efectos) motorPagarMano(*this, yo, 1);
			sacrificar(j.tributos);
			std::vector<int> idx = j.manoExtra;
			idx.push_back(j.mano);
			for (const std::string& s : deLaMano(idx)) aCementerio(yo, s);
			const int z = zonaLibre(j.zona);
			if (z < 0) return false;
			x.extra.erase(std::find(x.extra.begin(), x.extra.end(), j.carta));
			ponerMonstruo(yo, z, j.carta, false, false);
			invocado(z, V_INVOCACION_ESPECIAL);
			return true;
		}
		case J_RITUAL: {
			if (!principal() || !base || j.mano < 0 || j.mano2 < 0 || j.mano >= (int)x.mano.size() || j.mano2 >= (int)x.mano.size()) return false;
			const std::string magia = x.mano[(size_t)j.mano], ritual = x.mano[(size_t)j.mano2];
			if (!base->ritualCon(ritual, magia)) return false;   // (rama classic-probador: tambien las genericas)
			if (efectos && !motorPuedeInvocarM2(*this, yo, 2)) return false;   // (rama classic-motor2)
			int suma = 0;
			for (int k : j.manoExtra) {
				if (k < 0 || k >= (int)x.mano.size() || k == j.mano || k == j.mano2) return false;
				suma += nivel(x.mano[(size_t)k]);
			}
			for (int t : j.tributos) {
				if (t < 0 || t >= ZONAS || x.m[(size_t)t].vacia()) return false;
				suma += nivel(x.m[(size_t)t].id);
			}
			if (suma < nivel(ritual)) return false;
			if (efectos && motorSinSacrificios(*this)) return false;   // (Mask of Restrict)
			if (efectos && !motorPuedePagarMano(*this, yo, 2)) return false;   // (Chain Energy: la magia y el ritual)
			if (efectos) motorPagarMano(*this, yo, 2);
			sacrificar(j.tributos);
			std::vector<int> idx = j.manoExtra;
			idx.push_back(j.mano);
			idx.push_back(j.mano2);
			for (const std::string& s : deLaMano(idx))
				if (s != ritual) aCementerio(yo, s);
			const int z = zonaLibre(j.zona);
			if (z < 0) return false;
			ponerMonstruo(yo, z, ritual, false, false);
			invocado(z, V_INVOCACION_ESPECIAL);
			return true;
		}
		case J_ATACAR: {
			if (!puedeAtacar(yo, j.zona)) return false;
			Lado& y = l[(size_t)(1 - yo)];
			if (j.objetivo < 0 ? (y.monstruos() > 0 && !(efectos && motorAtaqueDirecto(*this, yo, j.zona))) : (j.objetivo >= ZONAS || y.m[(size_t)j.objetivo].vacia()))
				return false;
			if (j.objetivo < 0 && efectos && !motorPuedeDirecto(*this, yo, j.zona)) return false;   // (Zombyra the Dark)
			if (j.objetivo >= 0 && efectos && !motorAtacable(*this, 1 - yo, j.objetivo)) return false;   // (Hieracosphinx...)
			Monstruo& a = x.m[(size_t)j.zona];
			ef.m2Repeticion = a.ataquesExtra > 0 ? 2 : 1;   // (rama classic-motor2: lo que gasto la declaracion, para la repeticion)
			if (a.ataquesExtra > 0) a.ataquesExtra--;   // (Gray Wing: ataca otra vez)
			else a.ataco = true;
			if (efectos) motorDeclaraAtaque(*this, yo, j.zona);   // (Toons: 500 LP)
			ef.ataque = EstadoEfectos::Ataque{};
			ef.ataque.hay = true;
			ef.ataque.lado = yo;
			ef.ataque.zona = j.zona;
			ef.ataque.objetivo = j.objetivo;
			ef.ataque.uidA = a.uid;
			ef.ataque.uidO = j.objetivo >= 0 ? y.m[(size_t)j.objetivo].uid : 0;
			ef.ataque.nRival = y.monstruos();
			if (efectos) motorAtaqueDeclarado(*this);   // (Dreamsprite, Maiden with Eyes of Blue)
			suceso({ S_ATAQUE, yo, j.zona, ef.ataque.objetivo, 0, false, a.id });
			if (efectos) motorVentana(*this, Ventana{ V_ATAQUE, yo, j.zona, a.uid, a.id }, PEND_BATALLA);   // (Mirror Force...)
			else combate();
			return true;
		}
		case J_FASE:
			if (fase == F_PRINCIPAL1) {
				bool salta = efectos && ef.saltaBatalla[(size_t)yo];   // (Great Long Nose)
				if (salta) ef.saltaBatalla[(size_t)yo] = false;
				if (efectos && sinFaseBatallaM2()) salta = true;   // (rama classic-motor2: D.D. Borderline)
				irFase(turno <= 1 || salta ? F_PRINCIPAL2 : F_BATALLA);
				if (efectos && fase == F_BATALLA) motorVentana(*this, Ventana{ V_INICIO_BATALLA, yo, -1, 0, {} });   // (rapidas del rival)
			}
			else if (fase == F_BATALLA) {
				if (efectos && hayForzadosM2(*this)) return false;   // (rama classic-motor2: Amazoness Archers: deben atacar)
				if (efectos) {   // (rama classic-motor2: la ventana del final de la batalla; al cerrarse, terminarBatalla)
					motorVentana(*this, Ventana{ V_FIN_BATALLA, yo, -1, 0, {} }, PEND_FIN_BATALLA);
					return true;
				}
				irFase(F_PRINCIPAL2);
			}
			else if (fase == F_PRINCIPAL2) {
				irFase(F_FINAL);
				if (efectos) {
					motorFinTurno(*this);   // (Change of Heart devuelve el monstruo...)
					motorVentana(*this, Ventana{ V_FASE_FINAL, yo, -1, 0, {} }, PEND_FIN_TURNO);   // ultima ocasion del rival (MST, Call of the Haunted)
				} else if ((int)x.mano.size() <= limiteMano(*this, yo)) {
					pasarTurno();
				}
			} else if (fase == F_FINAL) {
				if ((int)x.mano.size() > limiteMano(*this, yo)) return false;
				pasarTurno();
			}
			return true;
		case J_DESCARTAR: {
			if (fase != F_FINAL || j.mano < 0 || j.mano >= (int)x.mano.size()) return false;
			const std::string id = x.mano[(size_t)j.mano];
			x.mano.erase(x.mano.begin() + j.mano);
			aCementerio(yo, id);
			if ((int)x.mano.size() <= limiteMano(*this, yo)) pasarTurno();
			return true;
		}
		default: break;
		}
		return false;
	}
};

// ------------------------------------------------------------------------------------------------- motor de efectos
// (rama classic-efectos) Diseno completo en docs/efectos.md. Resumen:
//  - Cada carta con efecto tiene una DefCarta (tablaCartas(): datos + funciones propias en C++): que objetivos toma,
//    sus costes (LP, descartes), cuando se puede activar (condicion, ademas de la velocidad de hechizo que sale del
//    subtipo de cartas_classic.txt), como se resuelve y cuanto vale para la IA. Las que no estan: sin efecto (se
//    pueden colocar como farol; el menu dice "Efecto aun no disponible").
//  - Activar = la carta pasa boca arriba a su zona, se pagan los costes y entra como eslabon en la cadena (pila).
//    Luego el otro lado puede responder (Duelo::ef.preg = P_RESPUESTA: activar algo de velocidad >= la del ultimo
//    eslabon, o pasar); cuando los dos pasan seguidos, la cadena se resuelve de arriba hacia abajo (LIFO).
//  - Ventanas de respuesta: tras una invocacion (normal, volteo, especial), una declaracion de ataque, una
//    activacion y la fase final del turno. El combate declarado espera a que se cierre su ventana (Mirror Force...).
//  - Resolver puede pedir una eleccion (P_ELEGIR: descartar, desempatar...): la cadena se detiene hasta J_ELEGIR.
//  - Efectos continuos (equipos, campos, Swords, Gravity Bind...) se recalculan con cada suceso (motorRecalcular).
enum Objetivo {
	O_NINGUNO = 0,
	O_MT,                     // una magia/trampa del campo (cualquiera, no esta)
	O_MT_RIVAL,               // una magia/trampa del rival
	O_MONSTRUO,               // un monstruo del campo
	O_MONSTRUO_RIVAL,         // un monstruo del rival
	O_MONSTRUO_RIVAL_ARRIBA,  // un monstruo boca arriba del rival
	O_MONSTRUO_ARRIBA,        // un monstruo boca arriba (cualquier lado): equipos
	O_MONSTRUO_PROPIO_ARRIBA, // un monstruo boca arriba propio
	O_CEM_MONSTRUO,           // un monstruo de cualquier cementerio (que se pueda invocar)
	O_CEM_MONSTRUO_PROPIO,    // un monstruo del cementerio propio
	O_ATACANTE,               // el monstruo que declaro el ataque (ventana de ataque)
	O_INVOCADO,               // el monstruo recien invocado (ventana de invocacion)
	O_ESLABON,                // la carta que se activo (ultimo eslabon de la cadena): contraataques
};
// cuando se dispara el efecto de un monstruo (tanda 5)
enum Disparo { D_NINGUNO = 0, D_VOLTEO, D_INVOCADO, D_AL_CEMENTERIO, D_DESTRUIDO_BATALLA, D_DESTRUYE_BATALLA, D_DANNO_DIRECTO,
               D_INVOCADO_NORMAL,     // solo invocacion normal (Breaker)
               D_NORMAL_O_VOLTEO,     // invocacion normal o volteo (Tsukuyomi)
               D_DANNO_BATALLA,       // hizo danno de batalla al rival (Airknight Parshath)
               D_A_CEMENTERIO,        // enviado al cementerio desde cualquier lugar (The White Stone of Legend)
               D_VOLTEO_INVOCACION,   // solo invocacion por volteo (Guardian Sphinx)
               D_INVOCADO_SACRIFICIO, // invocado normal con sacrificios (Zaborg, Mobius)
               D_NORMAL_O_VOLTEO_INV };   // invocado normal o por volteo (Don Turtle)

struct DefCarta {
	std::string id;
	int objetivo{ O_NINGUNO }, nObj{ 0 };
	int costeLP{ 0 };          // >0: fijo; -1: la mitad de los LP (Solemn Judgment)
	int descartes{ 0 };        // cartas de la mano como coste
	bool permanece{ false };   // continua, equipo, campo: se queda en el campo tras resolver
	bool ignicion{ false };    // monstruo: efecto que se activa en la fase principal (una vez por turno)
	int disparo{ D_NINGUNO };  // monstruo: efecto que se dispara solo (volteo, al ir al cementerio...)
	bool (*condicion)(const Duelo&, int lado, const Lugar& fuente){ nullptr };
	std::vector<Lugar> (*objetivos)(const Duelo&, int lado, const Lugar& fuente){ nullptr };
	void (*resolver)(Duelo&, Eslabon&){ nullptr };
	float (*valor)(const Duelo&, int lado, const std::vector<Lugar>& objs){ nullptr };   // IA: cuanto vale activarla ahora
	void (*alSalir)(Duelo&, int lado, const MagiaTrampa&){ nullptr };                   // deja el campo (equipos, vinculos)
	int (*modAtk)(const Duelo&, int ladoFuente, const MagiaTrampa*, int lado, int z){ nullptr };   // continuo: +ATK
	int (*modDef)(const Duelo&, int ladoFuente, const MagiaTrampa*, int lado, int z){ nullptr };   // continuo: +DEF
	bool (*impideAtaque)(const Duelo&, int ladoFuente, const MagiaTrampa*, int lado, int z){ nullptr };
	std::vector<Lugar> (*objetivosIA)(const Duelo&, int lado, const Lugar& fuente){ nullptr };   // IA: si la eleccion generica no sirve
	bool favorece{ false };    // IA: el objetivo sale ganando (equipos que suben ATK): mejor uno propio
	bool danna{ false };       // su efecto inflige danno (Barrel Behind the Door responde a esto)
	int atkPorContador{ 0 };   // monstruo: ATK por cada contador (Breaker)
	bool perfora{ false };     // monstruo: danno de batalla perforante (Airknight Parshath)
	// monstruo: invocacion especial desde la mano por su procedimiento (no usa la cadena): se puede / pagar
	bool (*puedeProcedimiento)(const Duelo&, int lado){ nullptr };
	void (*pagarProcedimiento)(Duelo&, int lado){ nullptr };
	void (*coste)(Duelo&, Eslabon&){ nullptr };   // coste propio al activar (quitar un contador...)
	// costes que elige quien activa (sacrificios de Obelisk / Crush Card Virus, destierros de Envoy): cuantos, los
	// candidatos dados los ya elegidos, y pagarlos
	int nCostes{ 0 };
	std::vector<Lugar> (*candCostes)(const Duelo&, int lado, const Lugar& fuente, const std::vector<Lugar>& ya){ nullptr };
	void (*pagarCostes)(Duelo&, int lado, const std::vector<Lugar>&){ nullptr };
	int (*elegirIA)(const Duelo&, const Eslabon&){ nullptr };   // IA: que elegir en su pregunta P_ELEGIR
	bool unaPorTurno{ false }; // "solo puedes activar 1 por turno"
	bool unaPorDuelo{ false }; // "solo 1 por duelo"
	bool pasoDanno{ false };   // se puede activar en el paso de danno (modifica ATK/DEF: Shrink, Reinforcements...)
	bool trasDanno{ false };   // (rama classic-reglas-oficiales) "cuando recibes danno": solo en la ventana V_DANNO
	bool repetible{ false };   // boca arriba en su zona, se vuelve a activar (Ultimate Offering, Uniones equipadas)
	bool unaVezRepetible{ false };
	bool repetibleRespuesta{ false };  // (y boca arriba se puede volver a usar en respuesta: Jam Defender, Skull Lair)   // (y solo 1 vez por turno: Uniones)
	bool sinLimite{ false };         // efecto de ignicion sin limite por turno (Cannon Soldier, Venus)
	bool rapidoMonstruo{ false };    // efecto rapido de monstruo (velocidad 2: se activa en respuesta; Maryokutai)
	bool desdeMano{ false };         // efecto rapido desde la mano descartandose (Kuriboh)
	bool equipoDesdeMano{ false };   // monstruo que se equipa desde la mano como una magia de equipo (Cocoon of Evolution)
	bool ignicionMano{ false };      // efecto de ignicion desde la mano descartandose (Thunder Dragon)
	bool alCampoRival{ false };      // su procedimiento lo invoca en el campo del rival (Lava Golem)
	int (*atkPropio)(const Duelo&, int lado, int z){ nullptr };   // monstruo: su propio +ATK/DEF (Slifer, Insect Queen)
	void (*espera)(Duelo&, int ladoFuente, const Lugar& fuente){ nullptr };   // fase de espera (de cualquiera)
	void (*finTurno)(Duelo&, int ladoFuente, const Lugar& fuente){ nullptr }; // fase final (de cualquiera)
};

// ---- utilidades del campo
inline std::string cartaEn(const Duelo& d, const Lugar& g)
{
	if (g.lado < 0 || g.lado > 1) return {};
	const Lado& x = d.l[(size_t)g.lado];
	switch (g.donde) {
	case EN_MONSTRUO: return g.i >= 0 && g.i < ZONAS ? x.m[(size_t)g.i].id : std::string();
	case EN_MT: return g.i >= 0 && g.i < ZONAS ? x.mt[(size_t)g.i].id : std::string();
	case EN_CAMPO: return x.campo.id;
	case EN_MANO: return g.i >= 0 && g.i < (int)x.mano.size() ? x.mano[(size_t)g.i] : std::string();
	case EN_CEMENTERIO: return g.i >= 0 && g.i < (int)x.cementerio.size() ? x.cementerio[(size_t)g.i] : std::string();
	case EN_DESTERRADO: return g.i >= 0 && g.i < (int)x.desterrados.size() ? x.desterrados[(size_t)g.i] : std::string();
	case EN_MAZO: return g.i >= 0 && g.i < (int)x.mazo.size() ? x.mazo[(size_t)g.i] : std::string();
	case EN_EXTRA: return g.i >= 0 && g.i < (int)x.extra.size() ? x.extra[(size_t)g.i] : std::string();
	default: return {};
	}
}
inline int uidEn(const Duelo& d, const Lugar& g)
{
	if (g.donde == EN_MONSTRUO && g.i >= 0 && g.i < ZONAS) return d.l[(size_t)g.lado].m[(size_t)g.i].uid;
	if (const MagiaTrampa* c = d.mtEn(g)) return c->uid;
	return 0;
}
inline std::string subtipoDe(const Duelo& d, const std::string& id)
{
	const Carta* c = d.carta(id);
	return c ? c->subtipo : std::string();
}
// velocidad de hechizo: 1 magias normales/continuas/equipo/campo/ritual y efectos de monstruo; 2 rapidas y trampas;
// 3 trampas de contraataque
inline int velocidadDe(const Duelo& d, const std::string& id, bool deMonstruo)
{
	if (deMonstruo) {
		const DefCarta* df = defCarta(id);
		return df && (df->rapidoMonstruo || df->desdeMano) ? 2 : 1;
	}
	const std::string st = subtipoDe(d, id);
	if (st == "trampa_contraataque") return 3;
	if (st == "magia_rapida" || st.rfind("trampa", 0) == 0) return 2;
	return 1;
}
inline bool esMagia(const Duelo& d, const std::string& id)
{
	const Carta* c = d.carta(id);
	return c && c->magia;
}
inline bool esTrampa(const Duelo& d, const std::string& id)
{
	const Carta* c = d.carta(id);
	return c && c->trampa;
}
inline bool arriba(const Monstruo& m) { return !m.vacia() && !m.bocaAbajo; }
inline int contarMonstruos(const Duelo& d, int lado, bool soloArriba = false)
{
	int n = 0;
	for (const Monstruo& m : d.l[(size_t)lado].m) n += !m.vacia() && (!soloArriba || !m.bocaAbajo);
	return n;
}
inline int contarMT(const Duelo& d, int lado, int sinUid = 0)
{
	int n = 0;
	for (const MagiaTrampa& c : d.l[(size_t)lado].mt) n += !c.vacia() && c.uid != sinUid;
	n += !d.l[(size_t)lado].campo.vacia() && d.l[(size_t)lado].campo.uid != sinUid;
	return n;
}
// lo que vale un monstruo del campo para quien lo controla (puntos ~ ATK; IA)
inline float valorMonstruo(const Duelo& d, const Monstruo& m)
{
	if (m.vacia()) return 0.0f;
	if (m.bocaAbajo && !m.visto) return 450.0f + 650.0f;
	return 450.0f + 0.5f * (float)std::max(d.atkM(m), d.defM(m));
}
inline float valorMT(const Duelo& d, const MagiaTrampa& c)
{
	if (c.vacia()) return 0.0f;
	if (c.bocaAbajo) return 420.0f;   // (puede ser cualquier cosa)
	const std::string st = subtipoDe(d, c.id);
	return st == "magia_equipo" || st == "magia_continua" || st == "trampa_continua" || st == "magia_campo" ? 480.0f : 150.0f;
}
// lo que vale una carta de la mano (para descartarla: la de menos valor primero)
inline float valorEnMano(const Duelo& d, const std::string& id)
{
	const Carta* c = d.carta(id);
	if (!c) return 0.0f;
	if (c->monstruo && c->noInvocable && defCarta(id) && defCarta(id)->puedeProcedimiento) return (float)c->atk;   // (se invoca por su procedimiento)
	if (id.find("forbidden_one") != std::string::npos) return 2500.0f;   // (rama classic-mazos-torneo: Exodia se junta en la mano)
	if (c->monstruo) return c->noInvocable || c->clase == "ritual" ? 150.0f : (float)std::max(c->atk, c->def) * (c->nivel >= 7 ? 0.6f : 1.0f);
	return defCarta(id) ? 900.0f : 350.0f;
}

// ---- tabla de cartas
inline std::unordered_map<std::string, DefCarta>& tablaCartas();   // (las cartas: mas abajo)
inline const DefCarta* defCarta(const std::string& id)
{
	const auto& t = tablaCartas();
	auto it = t.find(id);
	return it == t.end() ? nullptr : &it->second;
}

// ---- objetivos
inline bool ignoraMagia(const Duelo& d, int lado, int z, int activa);
inline bool ignoraTrampa(const Duelo& d, int lado, int z, int activa);
inline bool fueraPorMetalsilver(const Duelo& d, const Lugar& g, int activa);
inline std::vector<Lugar> objetivosDe(const Duelo& d, int lado, const DefCarta& df, const Lugar& fuente)
{
	if (df.objetivos) {
		std::vector<Lugar> r = df.objetivos(d, lado, fuente);
		if (esMagia(d, cartaEn(d, fuente)))   // (Silent Swordsman, Horus LV6, Kay'est...)
			r.erase(std::remove_if(r.begin(), r.end(), [&](const Lugar& g) { return g.donde == EN_MONSTRUO && ignoraMagia(d, g.lado, g.i, lado); }), r.end());
		r.erase(std::remove_if(r.begin(), r.end(), [&](const Lugar& g) { return g.donde == EN_MONSTRUO && protegidoPorServant(d, g.lado, g.i, lado); }), r.end());
		if (df.nObj == 1)
			r.erase(std::remove_if(r.begin(), r.end(), [&](const Lugar& g) { return g.donde == EN_MONSTRUO && fueraPorMetalsilver(d, g, lado); }), r.end());
		filtroObjetivosM2(d, lado, r);   // (rama classic-motor2: King Dragun...)
		return r;
	}
	std::vector<Lugar> r;
	const int otro = 1 - lado;
	const int uidFuente = uidEn(d, fuente);
	const bool deMagia = esMagia(d, cartaEn(d, fuente));
	bool lordOfD = false;
	for (const Lado& lx : d.l)
		for (const Monstruo& mx : lx.m) lordOfD |= arriba(mx) && mx.id == "lord_of_d";
	auto mts = [&](int a) {
		for (int z = 0; z < ZONAS; z++) {
			const MagiaTrampa& c = d.l[(size_t)a].mt[(size_t)z];
			if (!c.vacia() && c.uid != uidFuente) r.push_back({ a, EN_MT, z });
		}
		const MagiaTrampa& c = d.l[(size_t)a].campo;
		if (!c.vacia() && c.uid != uidFuente) r.push_back({ a, EN_CAMPO, ZONA_CAMPO });
	};
	auto mons = [&](int a, bool soloArriba) {
		for (int z = 0; z < ZONAS; z++) {
			const Monstruo& m = d.l[(size_t)a].m[(size_t)z];
			if (!m.bocaAbajo && m.id == "obelisk_the_tormentor") continue;   // (nadie puede elegirlo con efectos)
			if (!m.bocaAbajo && lordOfD && d.carta(m.id) && d.carta(m.id)->raza == "Dragón") continue;   // (Lord of D.)
			if (deMagia && ignoraMagia(d, a, z, lado)) continue;   // (Silent Swordsman, Horus LV6, Kay'est...)
			if (esTrampa(d, cartaEn(d, fuente)) && ignoraTrampa(d, a, z, lado)) continue;   // (Gora Turtle of Illusion)
			if (!m.vacia() && protegidoPorServant(d, a, z, lado)) continue;   // (Horus' Servant)
			if (!m.vacia() && df.nObj == 1 && fueraPorMetalsilver(d, { a, EN_MONSTRUO, z }, lado)) continue;   // (Metalsilver Armor)
			if (!m.vacia() && (!soloArriba || !m.bocaAbajo)) r.push_back({ a, EN_MONSTRUO, z });
		}
	};
	auto cem = [&](int a) {
		const Lado& x = d.l[(size_t)a];
		for (int i = 0; i < (int)x.cementerio.size(); i++) {
			const Carta* c = d.carta(x.cementerio[(size_t)i]);
			if (c && c->monstruo && !c->noInvocable && c->subtipo != "espiritu" && c->id != "the_winged_dragon_of_ra" && c->id != "ancient_gear_golem" && !fusionContacto(c->id)) r.push_back({ a, EN_CEMENTERIO, i });
		}
	};
	switch (df.objetivo) {
	case O_MT: mts(lado), mts(otro); break;
	case O_MT_RIVAL: mts(otro); break;
	case O_MONSTRUO: mons(lado, false), mons(otro, false); break;
	case O_MONSTRUO_RIVAL: mons(otro, false); break;
	case O_MONSTRUO_RIVAL_ARRIBA: mons(otro, true); break;
	case O_MONSTRUO_ARRIBA: mons(lado, true), mons(otro, true); break;
	case O_MONSTRUO_PROPIO_ARRIBA: mons(lado, true); break;
	case O_CEM_MONSTRUO: cem(lado), cem(otro); break;
	case O_CEM_MONSTRUO_PROPIO: cem(lado); break;
	case O_ATACANTE: {
		int la = -1, za = -1;
		if (d.ef.ataque.hay && d.porUid(d.ef.ataque.uidA, &la, &za)) r.push_back({ la, EN_MONSTRUO, za });
		break;
	}
	case O_INVOCADO: {
		int la = -1, za = -1;
		const Ventana& v = d.ef.ventana;
		if ((v.tipo == V_INVOCACION_NORMAL || v.tipo == V_VOLTEO || v.tipo == V_INVOCACION_ESPECIAL) && d.porUid(v.uid, &la, &za)) r.push_back({ la, EN_MONSTRUO, za });
		break;
	}
	default: break;
	}
	// los cementerios cuentan cada carta una vez (dos copias iguales = el mismo objetivo para elegir)
	if (df.objetivo == O_CEM_MONSTRUO || df.objetivo == O_CEM_MONSTRUO_PROPIO) {
		std::vector<Lugar> u;
		for (const Lugar& g : r) {
			bool rep = false;
			for (const Lugar& h : u) rep |= h.lado == g.lado && cartaEn(d, h) == cartaEn(d, g);
			if (!rep) u.push_back(g);
		}
		r.swap(u);
	}
	filtroObjetivosM2(d, lado, r);   // (rama classic-motor2)
	return r;
}

// Jinzo boca arriba: las trampas no se activan y sus efectos en el campo se niegan
inline bool jinzoEnCampo(const Duelo& d)
{
	for (const Lado& x : d.l)
		for (const Monstruo& m : x.m)
			if (arriba(m) && m.id == "jinzo" && !efectoNegado(d, m)) return true;
	for (const Lado& x : d.l)   // (Royal Decree: atajo, como Jinzo; Talisman of Trap Sealing)
		if (x.tieneBocaArriba("royal_decree") || x.tieneBocaArriba("talisman_of_trap_sealing")) return true;
	return false;
}
// ---- costes elegidos (sacrificios, destierros): se pueden pagar? (eligiendo de a uno el primero posible)
inline std::vector<Lugar> costesIA(const Duelo& d, int lado, const DefCarta& df, const Lugar& f);
inline bool costesDeProcedimiento(const DefCarta& df) { return df.puedeProcedimiento != nullptr; }
inline bool costesPosibles(const Duelo& d, int lado, const DefCarta& df, const Lugar& f)
{
	if (df.nCostes <= 0 || !df.candCostes) return true;
	if (costesDeProcedimiento(df) && f.donde != EN_MANO) return true;   // (los costes son de la invocacion, no del efecto)
	return (int)costesIA(d, lado, df, f).size() == df.nCostes;
}
// (control final) el descarte que pide el texto: Light of Judgment y Archlord Zerato descartan un monstruo de LUZ
inline bool descarteVale(const Duelo& d, const std::string& carta, const std::string& descartada)
{
	if (carta == "light_of_judgment" || carta == "archlord_zerato") {
		const Carta* c = d.carta(descartada);
		return c && c->monstruo && c->atributo == "LUZ";
	}
	return true;
}
inline bool costesValidos(const Duelo& d, int lado, const DefCarta& df, const Lugar& f, const std::vector<Lugar>& c)
{
	if (df.nCostes <= 0 || !df.candCostes || (costesDeProcedimiento(df) && f.donde != EN_MANO)) return c.empty();
	if ((int)c.size() != df.nCostes) return false;
	std::vector<Lugar> ya;
	for (const Lugar& g : c) {
		const std::vector<Lugar> cand = df.candCostes(d, lado, f, ya);
		if (std::find(cand.begin(), cand.end(), g) == cand.end() || std::find(ya.begin(), ya.end(), g) != ya.end()) return false;
		ya.push_back(g);
	}
	return true;
}
// The End of Anubis boca arriba: se niegan los efectos que eligen cartas del cementerio o que se activan alli
inline bool anubisEnCampo(const Duelo& d)
{
	for (const Lado& x : d.l)
		for (const Monstruo& m : x.m)
			if (arriba(m) && m.id == "the_end_of_anubis") return true;
	return false;
}
// (rama classic-reglas-oficiales) la ventana justo despues del danno es la de este lado (cartas "cuando recibes danno")
inline bool enVentanaDanno(const Duelo& d, int lado) { return d.ef.ventana.tipo == V_DANNO && d.ef.ventana.lado == lado; }
// ---- se puede activar? "" = si; si no, la clave del motivo (textoEfecto)
// comoRespuesta: en una ventana de respuesta (pregunta P_RESPUESTA o para saber si hay que preguntar)

// (rama classic-torneo-extras) monstruo Geminis boca arriba en el campo que aun es "monstruo normal": se puede invocar de
// nuevo (invocacion normal del turno) para que gane su efecto (Il Blud). En la mano, el cementerio o boca abajo no
inline bool esGeminis(const Duelo& d, const std::string& id) { return subtipoDe(d, id) == "geminis"; }
inline bool geminisPendiente(const Duelo& d, const Lugar& f)
{
	if (f.donde != EN_MONSTRUO || f.i < 0 || f.i >= ZONAS || f.lado < 0 || f.lado > 1) return false;
	const Monstruo& m = d.l[(size_t)f.lado].m[(size_t)f.i];
	return !m.vacia() && !m.bocaAbajo && !m.geminado && esGeminis(d, m.id);
}
// su efecto solo cuenta invocado de nuevo (y boca arriba)
inline bool geminisActivo(const Monstruo& m) { return !m.vacia() && !m.bocaAbajo && m.geminado; }

inline std::string motivoNoActivar(const Duelo& d, int lado, const Lugar& f, bool comoRespuesta)
{
	if (!d.efectos || d.ganador >= 0) return "ef.no";
	const std::string id = cartaEn(d, f);
	if (id.empty()) return "ef.no";
	const Carta* c = d.carta(id);
	const DefCarta* df = defCarta(id);
	if (!c) return "ef.no";
	if (!df) return "ef.no_disponible";
	const Lado& x = d.l[(size_t)lado];
	const std::string st = c->subtipo;
	const bool deMonstruo = f.donde == EN_MONSTRUO;
	if (deMonstruo && f.lado == lado && geminisPendiente(d, f)) {   // (rama classic-torneo-extras) Geminis (regla, no efecto): invocarlo de nuevo con la normal del turno
		if (comoRespuesta || d.activo != lado || d.ocupado() || !d.principal()) return "ef.no_momento";
		if (x.invocoNormal) return "ef.ya_invoco";
		if (!motorPuedeInvocar(d, lado, id, 0) || !motorPuedeInvocarM2(d, lado, 0)) return "ef.no_condicion";
		return {};
	}
	if (deMonstruo && f.lado >= 0 && f.i >= 0 && f.i < ZONAS && efectoNegado(d, d.l[(size_t)f.lado].m[(size_t)f.i])) return "ef.no_momento";   // (Skill Drain...)
	if (f.donde == EN_MT && f.i >= 0 && f.i < ZONAS && std::find(d.ef.xing.begin(), d.ef.xing.end(), d.l[(size_t)f.lado].mt[(size_t)f.i].uid) != d.ef.xing.end())
		return "ef.no_momento";   // (Xing Zhen Hu)
	const int vel = velocidadDe(d, id, deMonstruo || (f.donde == EN_MANO && c->monstruo));   // (Kuriboh: efecto de monstruo desde la mano)
	if (d.ef.ventana.tipo == V_ESPERA && d.ef.cadena.empty() && !esCartaEspera(id)) return "ef.no_momento";   // (rama classic-motor2: en la espera, solo las cartas de ese momento)
	if (d.ef.ventana.tipo == V_COLOCADO && d.ef.cadena.empty() && id != "shadow_of_eyes") return "ef.no_momento";   // (rama classic-motor2: al colocar, solo Shadow of Eyes)
	if (d.ef.ventana.tipo == V_DANNO && d.ef.cadena.empty() && !df->trasDanno) return "ef.no_momento";   // (rama classic-reglas-oficiales: tras el danno, solo esas cartas)
	// el momento
	if (comoRespuesta) {
		const bool esperaPropia = d.ef.ventana.tipo == V_ESPERA && d.ef.cadena.empty() && d.activo == lado && id == "curse_of_fiend";   // (motor2: magia normal de tu fase de espera)
		if (vel < 2 && !esperaPropia) return "ef.no_momento";
		if (!d.ef.cadena.empty() && vel < std::max(2, d.ef.cadena.back().velocidad)) return "ef.no_velocidad";
		if (!d.ef.cadena.empty() && d.ef.cadena.front().carta == "mischief_of_the_time_goddess" && !d.ef.cadena.front().deMonstruo)
			return "ef.no_momento";   // (Mischief of the Time Goddess: nadie responde a su activacion)
	} else {
		if (d.activo != lado || d.ocupado()) return "ef.no_momento";
		if (vel == 1 && !d.principal()) return "ef.solo_principal";
		if (d.fase != F_PRINCIPAL1 && d.fase != F_PRINCIPAL2 && d.fase != F_BATALLA) return "ef.no_momento";
	}
	// de donde
	if (f.lado != lado) return "ef.no";
	if (c->trampa && jinzoBloquea(d, lado)) return "ef.jinzo";   // (Amplifier)
	if (c->trampa && d.ef.ventana.tipo == V_INVOCACION_NORMAL && (d.ef.ventana.carta == "creeping_doom_manta" || d.ef.ventana.carta == "eagle_eye" || d.ef.ventana.carta == "invasion_of_flames" ||
	                                                             d.ef.ventana.carta == "tactical_espionage_expert"))
		return "ef.no_momento";
	if (d.ef.ventana.tipo == V_PASO_DANNO && vel < 3 && !df->pasoDanno) return "ef.no_momento";   // (paso de danno)
	if ((c->magia || c->trampa) && d.ef.sinMTTurno == d.turno) return "ef.no_momento";   // (Sasuke Samurai #2)
	if (c->trampa && d.ef.sinTrampasTurno[(size_t)lado] == d.turno) return "ef.no_momento";   // (Triangle Ecstasy Spark)
	if ((c->magia || c->trampa) && ondaFria(d)) return "ef.no_momento";   // (Cold Wave)
	if (f.donde == EN_MANO && !motorPuedePagarMano(d, lado, 1)) return "ef.sin_lp";   // (Chain Energy)
	if (f.donde == EN_MANO && esPrestada(d, lado, id) && d.l[(size_t)lado].lp <= 2000) return "ef.sin_lp";   // (Graverobber)
	if ((c->magia || c->trampa) && d.ef.ataque.hay && d.ef.ataque.lado != lado)   // Ancient Gear Golem ataca: sin magias/trampas
		if (const Monstruo* a = d.porUid(d.ef.ataque.uidA))
			if (a->id == "ancient_gear_golem" || a->id == "ancient_gear_soldier" || a->id == "ancient_gear_beast") return "ef.no_momento";
	if (c->magia && d.ef.sinMagiasHasta[(size_t)lado] >= d.turno) return "ef.no_momento";   // (Sonic Jammer)
	if (c->trampa && d.fase == F_BATALLA)   // Mirage Dragon: el rival no activa trampas en la fase de batalla
		for (const Monstruo& m : d.l[(size_t)(1 - lado)].m)
			if (arriba(m) && (m.id == "mirage_dragon" || m.id == "pitch_black_warwolf")) return "ef.no_momento";
	if (st == "magia_rapida")   // Invader of Darkness: el rival no activa magias rapidas
		for (const Monstruo& m : d.l[(size_t)(1 - lado)].m)
			if (arriba(m) && m.id == "invader_of_darkness") return "ef.no_momento";
	if ((df->descartes > 0 || df->desdeMano) && monstruoArriba(d, -1, "goblin_of_greed")) return "ef.no_momento";   // (Goblin of Greed)
	if (std::find(d.ef.sellados[(size_t)lado].begin(), d.ef.sellados[(size_t)lado].end(), id) != d.ef.sellados[(size_t)lado].end())
		return "ef.no_momento";   // (Cursed Seal of the Forbidden Spell)
	if (c->magia && magiasProhibidas(d)) return "ef.no_momento";   // (Spell Canceller, Imperial Order, Silent Swordsman LV7)
	if (c->magia && hayBocaArriba(d, "anti_spell_fragrance") && !jinzoEnCampo(d)) {   // (Anti-Spell Fragrance)
		if (f.donde == EN_MANO) return "ef.no_momento";
		if (const MagiaTrampa* k = d.mtEn(f))
			if (k->bocaAbajo && k->turnoColocada == d.turno) return "ef.no_momento";
	}
	if (f.donde == EN_MANO && !c->monstruo && hayBocaArriba(d, "spatial_collapse") && !jinzoEnCampo(d) && cartasEnCampo(d, lado) >= 5) return "ef.no_momento";   // (Spatial Collapse)
	if (f.donde == EN_MANO && c->monstruo && df->desdeMano) {   // efecto rapido desde la mano (Kuriboh): se descarta
		if (!comoRespuesta) return "ef.no_momento";
		if (d.ef.ventana.tipo == V_PASO_DANNO && !df->pasoDanno) return "ef.no_momento";
		return !df->condicion || df->condicion(d, lado, f) ? std::string() : std::string("ef.no_condicion");
	}
	if (f.donde == EN_MANO && c->monstruo && df->ignicionMano) {   // (Thunder Dragon: se descarta en tu fase principal)
		if (comoRespuesta || d.activo != lado || d.ocupado() || !d.principal()) return "ef.no_momento";
		return !df->condicion || df->condicion(d, lado, f) ? std::string() : std::string("ef.no_condicion");
	}
	if (f.donde == EN_MANO && c->monstruo && df->equipoDesdeMano) {   // (Cocoon of Evolution: como una magia de equipo)
		if (comoRespuesta || d.activo != lado || d.ocupado() || !d.principal()) return "ef.no_momento";
		if (x.libreMT() < 0) return "ef.sin_zona";
	} else if (f.donde == EN_MANO && c->monstruo) {   // invocacion especial por su procedimiento (Envoy, Chaos Emperor...)
		if (!df->puedeProcedimiento || comoRespuesta || d.activo != lado || d.ocupado() || !d.principal()) return "ef.no_momento";
		if (x.libre() < 0) return "ef.sin_zona_monstruo";
		if (!df->puedeProcedimiento(d, lado) || !motorPuedeInvocar(d, lado, id, 0) || !motorPuedeInvocarM2(d, lado, 2)) return "ef.no_condicion";
		return costesPosibles(d, lado, *df, f) ? std::string() : std::string("ef.sin_coste");
	}
	if (deMonstruo) {
		const Monstruo& m = x.m[(size_t)f.i];
		if (m.bocaAbajo || (!df->ignicion && !df->rapidoMonstruo) || (comoRespuesta && !df->rapidoMonstruo) || (!comoRespuesta && !df->ignicion))
			return "ef.no_momento";
		if (selladoPorEspada(d, m.uid)) return "ef.no";   // (Orichalcos Sword of Sealing)
		if (!df->sinLimite && std::find(d.ef.usadosTurno.begin(), d.ef.usadosTurno.end(), m.uid) != d.ef.usadosTurno.end()) return "ef.una_vez";
	} else if (f.donde == EN_MANO) {
		const bool makyura = c->trampa && d.ef.makyura[(size_t)lado] == d.turno;   // (Makyura the Destructor: trampas desde la mano)
		if (!c->magia && !df->equipoDesdeMano && !makyura) return "ef.trampa_colocada";   // las trampas se colocan primero
		if (d.activo != lado && !makyura) return "ef.no_momento";
		if (st != "magia_campo" && x.libreMT() < 0) return "ef.sin_zona";
	} else if (f.donde == EN_MT || f.donde == EN_CAMPO) {
		const MagiaTrampa* mt = d.mtEn(f);
		if (!mt || mt->vacia()) return "ef.no";
		if (!mt->bocaAbajo) {
			if (!df->repetible) return "ef.ya_activa";
			if (!(df->repetibleRespuesta && comoRespuesta) && (comoRespuesta || d.activo != lado || !d.principal())) return "ef.no_momento";   // (atajo 4)
			if (df->unaVezRepetible && std::find(d.ef.usadosTurno.begin(), d.ef.usadosTurno.end(), mt->uid) != d.ef.usadosTurno.end()) return "ef.una_vez";
		}
		if (c->trampa && mt->turnoColocada >= d.turno && !(x.tieneBocaArriba("temple_of_the_kings") && d.ef.templo[(size_t)lado] != d.turno))
			return "ef.colocada_este_turno";
		if (st == "magia_rapida" && mt->turnoColocada >= d.turno) return "ef.colocada_este_turno";
		if (c->magia && d.activo != lado && st != "magia_rapida") return "ef.no_momento";
	} else {
		return "ef.no";
	}
	if (df->unaPorTurno && std::find(d.ef.porTurno[(size_t)lado].begin(), d.ef.porTurno[(size_t)lado].end(), id) != d.ef.porTurno[(size_t)lado].end())
		return "ef.una_vez";
	if (df->unaPorDuelo && std::find(d.ef.porDuelo[(size_t)lado].begin(), d.ef.porDuelo[(size_t)lado].end(), id) != d.ef.porDuelo[(size_t)lado].end())
		return "ef.una_por_duelo";
	if (df->condicion && !df->condicion(d, lado, f)) return "ef.no_condicion";
	if (c->invocaEspecial && !motorPuedeInvocarM2(d, lado, 2)) return "ef.no_condicion";   // (rama classic-motor2: The Last Warrior, Jowgen...)
	if (df->nObj > 0 && (int)objetivosDe(d, lado, *df, f).size() < df->nObj) return "ef.sin_objetivo";
	const int coste = costeLPDe(d, lado, *df);   // (Spell Economics)
	if (coste > 0 && x.lp <= coste) return "ef.sin_lp";
	if (df->descartes > 0 && (int)x.mano.size() - (f.donde == EN_MANO ? 1 : 0) < df->descartes) return "ef.sin_descarte";
	if (!costesPosibles(d, lado, *df, f)) return "ef.sin_coste";
	return {};
}

// las cartas que este lado puede activar ahora (de la mano, colocadas y efectos de monstruo)
inline std::vector<Lugar> activables(const Duelo& d, int lado, bool comoRespuesta)
{
	std::vector<Lugar> r;
	if (!d.efectos) return r;
	const Lado& x = d.l[(size_t)lado];
	for (int k = 0; k < (int)x.mano.size(); k++) {
		const Carta* c = d.carta(x.mano[(size_t)k]);
		const DefCarta* dc = c ? defCarta(c->id) : nullptr;
		if (!c || !dc || !(c->magia || (c->monstruo && (dc->puedeProcedimiento || dc->desdeMano || dc->equipoDesdeMano || dc->ignicionMano)))) continue;
		bool repetida = false;   // (dos copias en la mano: una opcion)
		for (const Lugar& g : r) repetida |= g.donde == EN_MANO && cartaEn(d, g) == c->id;
		if (!repetida && motivoNoActivar(d, lado, { lado, EN_MANO, k }, comoRespuesta).empty()) r.push_back({ lado, EN_MANO, k });
	}
	for (int z = 0; z < ZONAS; z++)
		if (!x.mt[(size_t)z].vacia() && motivoNoActivar(d, lado, { lado, EN_MT, z }, comoRespuesta).empty()) r.push_back({ lado, EN_MT, z });
	if (!x.campo.vacia() && motivoNoActivar(d, lado, { lado, EN_CAMPO, ZONA_CAMPO }, comoRespuesta).empty()) r.push_back({ lado, EN_CAMPO, ZONA_CAMPO });
	for (int z = 0; z < ZONAS; z++)
		if (!x.m[(size_t)z].vacia() && motivoNoActivar(d, lado, { lado, EN_MONSTRUO, z }, comoRespuesta).empty()) r.push_back({ lado, EN_MONSTRUO, z });
	return r;
}
inline Jugada jugadaActivar(const Lugar& f)
{
	Jugada j;
	j.tipo = J_ACTIVAR;
	if (f.donde == EN_MANO) j.mano = f.i;
	else j.zona = f.donde == EN_CAMPO ? ZONA_CAMPO : f.i;
	j.deMonstruo = f.donde == EN_MONSTRUO;
	return j;
}
inline Lugar fuenteDe(const Jugada& j, int lado)
{
	if (j.mano >= 0) return { lado, EN_MANO, j.mano };
	if (j.deMonstruo) return { lado, EN_MONSTRUO, j.zona };
	if (j.zona == ZONA_CAMPO) return { lado, EN_CAMPO, ZONA_CAMPO };
	return { lado, EN_MT, j.zona };
}

// ---- la cadena
inline void cerrarVentana(Duelo& d);
inline void resolverCadena(Duelo& d);
inline void seguirTrasCadena(Duelo& d);
inline bool negadoPorEfecto(Duelo& d, Eslabon& e);
// cada magia que resuelve pone un contador de magia (max 3) en Skilled White Magician / Skilled Dark Magician
inline void contadorMagia(Duelo& d)
{
	for (Lado& x : d.l)
		for (Monstruo& m : x.m)
			if (!m.vacia() && !m.bocaAbajo && (m.id == "skilled_white_magician" || m.id == "skilled_dark_magician" || m.id == "royal_magical_library"))
				m.contadores = std::min(3, m.contadores + 1);
			else if (!m.vacia() && !m.bocaAbajo && (m.id == "magical_marionette" || m.id == "blast_magician" || m.id == "legendary_flame_lord")) m.contadores++;   // (sin tope)
}
inline void ofrecer(Duelo& d, int lado);
inline void pasar(Duelo& d, int lado)
{
	EstadoEfectos& e = d.ef;
	if (d.ganador >= 0) return;
	if (e.cadena.empty()) {
		if ((e.ventana.tipo == V_PASO_DANNO || e.ventana.tipo == V_ESPERA) && !e.pasoDannoSegundo) {   // (el paso de danno y la fase de espera (motor2): los dos tienen su ocasion)
			e.pasoDannoSegundo = true;
			ofrecer(d, 1 - lado);
			return;
		}
		cerrarVentana(d);
		return;
	}
	if (++e.pases >= 2) {
		resolverCadena(d);
		return;
	}
	ofrecer(d, 1 - lado);
}
inline void ofrecer(Duelo& d, int lado)
{
	if (d.ganador >= 0) return;
	if (d.preguntarSiempre[(size_t)lado] || !activables(d, lado, true).empty()) {   // (rama classic-ciclos: Siempre)
		d.ef.preg = Pregunta{};
		d.ef.preg.tipo = P_RESPUESTA;
		d.ef.preg.lado = lado;
		return;
	}
	pasar(d, lado);
}
inline void agregarEslabon(Duelo& d, Eslabon e)
{
	EstadoEfectos& s = d.ef;
	if (s.cadena.empty() && s.ventana.tipo == V_NINGUNA) {
		s.ventana = Ventana{};
		s.ventana.tipo = V_ACTIVACION;
		s.ventana.lado = e.lado;
		s.ventana.carta = e.carta;
	}
	if (s.ventana.tipo == V_ATAQUE && e.lado != s.ventana.lado) s.castigos[(size_t)s.ventana.lado]++;
	e.ventana = s.ventana;
	s.cadena.push_back(e);
	s.pases = 0;
	ofrecer(d, 1 - e.lado);
}
// los efectos disparados (volteo, al cementerio...) arman una cadena nueva: primero los del turno
inline void iniciarDisparos(Duelo& d)
{
	EstadoEfectos& s = d.ef;
	std::vector<Eslabon> lst;
	lst.swap(s.disparos);
	std::stable_sort(lst.begin(), lst.end(), [&](const Eslabon& a, const Eslabon& b) { return (a.lado == d.activo) > (b.lado == d.activo); });
	if (s.ventana.tipo == V_NINGUNA) {
		s.ventana = Ventana{};
		s.ventana.tipo = V_DISPARO;
		s.ventana.lado = lst[0].lado;
	}
	for (Eslabon& e : lst) {
		e.ventana = s.ventana;
		s.cadena.push_back(e);
		d.suceso({ e.deMonstruo ? S_ACTIVA_EFECTO : S_ACTIVA_MT, e.lado, e.fuente.donde == EN_CAMPO ? ZONA_CAMPO : e.fuente.i, -1, (int)s.cadena.size(),
		           !e.deMonstruo, e.carta });
	}
	s.pases = 0;
	ofrecer(d, 1 - s.cadena.back().lado);
}
// termina un eslabon: la magia/trampa normal (o negada) se va al cementerio; la continua/equipo se queda
inline void terminarEslabon(Duelo& d, const Eslabon& e)
{
	if (e.deMonstruo) return;
	const DefCarta* df = defCarta(e.carta);
	MagiaTrampa* c = d.mtEn(e.fuente);
	if (!c || c->vacia() || c->uid != e.uidFuente) return;   // (ya no esta: destruida en la cadena)
	const bool queda = df && df->permanece && !e.negado && e.valor != -1;
	if (!queda) d.mtAlCementerio(e.fuente.lado, e.fuente.donde == EN_CAMPO ? ZONA_CAMPO : e.fuente.i);
}
// rama classic-probador: Appropriate tras el eslabon que hizo robar al rival (2 cartas por robo, no por carta)
inline void apropiarPendiente(Duelo& d)
{
	for (int a = 0; a < 2; a++) {
		if (!d.ef.apropiar[(size_t)a]) continue;
		d.ef.apropiar[(size_t)a] = false;
		if (jinzoEnCampo(d) || !d.l[(size_t)a].tieneBocaArriba("appropriate")) continue;
		d.ef.apropiando = true;
		d.robarEfecto(a);
		d.robarEfecto(a);
		d.ef.apropiando = false;
	}
	// (despues de Appropriate, que tambien roba; Solemn Wishes y Silent Magician LV4: una vez por robo del eslabon, aunque sean varias cartas)
	for (int a = 0; a < 2; a++) {
		if (!d.ef.roboEnEslabon[(size_t)a]) continue;
		d.ef.roboEnEslabon[(size_t)a] = false;
		if (d.l[(size_t)a].tieneBocaArriba("solemn_wishes")) d.ganarLP(a, 500);
		for (Monstruo& m : d.l[(size_t)(1 - a)].m)
			if (arriba(m) && m.id == "silent_magician_lv4") m.contadores = std::min(5, m.contadores + 1);
	}
}
inline void resolverCadena(Duelo& d)
{
	EstadoEfectos& s = d.ef;
	if (!s.resolviendo) {
		s.resolviendo = true;
		d.suceso({ S_CADENA, s.cadena.empty() ? 0 : s.cadena.back().lado, -1, -1, (int)s.cadena.size() });
	}
	while (!s.cadena.empty() && d.ganador < 0) {
		const DefCarta* df = defCarta(s.cadena.back().carta);
		Eslabon& top = s.cadena.back();
		bool sigue = true;   // la carta sigue en su lugar (las continuas/equipos destruidas en la cadena no aplican nada)
		if (!top.deMonstruo) {
			const MagiaTrampa* c = d.mtEn(top.fuente);
			sigue = c && !c->vacia() && c->uid == top.uidFuente;
		}
		if (top.negado) {
			// (el aviso "Negado" ya salio al negarlo)
		} else if (negadoPorEfecto(d, top)) {
			d.suceso({ S_NEGADO, top.lado, top.fuente.i, -1, 0, !top.deMonstruo, top.carta });
			if (!top.deMonstruo && (esMagia(d, top.carta) || esTrampa(d, top.carta)) && top.valor == -2) top.negado = true;   // (Freed / Frontier: se destruye)
		} else if (!top.deMonstruo && esTrampa(d, top.carta) && jinzoEnCampo(d)) {
			d.suceso({ S_NEGADO, top.lado, top.fuente.i, -1, 0, true, top.carta });   // (Jinzo niega los efectos de trampa)
		} else if (df && df->resolver && (sigue || !df->permanece)) {
			df->resolver(d, top);
			d.recalcular();
			if (s.preg.tipo != P_NADA) return;   // espera una eleccion (J_ELEGIR sigue desde aqui)
		}
		apropiarPendiente(d);
		const Eslabon fin = s.cadena.back();
		for (size_t k = 0; k < fin.obj.size(); k++) {   // (Spirit Reaper elegido por un efecto: se destruye)
			if (fin.obj[k].donde != EN_MONSTRUO || fin.negado) continue;
			int la = -1, z = -1;
			const Monstruo* m = d.porUid(fin.uidObj[k], &la, &z);
			if (m && arriba(*m) && (m->id == "spirit_reaper" || m->id == "reaper_on_the_nightmare")) d.alCementerio(la, z);   // (motor2: Reaper on the Nightmare)
		}
		s.cadena.pop_back();
		if (!fin.deMonstruo && !fin.negado && esMagia(d, fin.carta)) contadorMagia(d);   // (Skilled White/Dark Magician)
		if (!fin.deMonstruo && !fin.negado) motorMagiaResueltaM2(d, fin.carta);   // (rama classic-motor2: Des Volstgalph)
		terminarEslabon(d, fin);
		s.resueltos++;
		d.suceso({ S_RESUELVE, fin.lado, fin.fuente.i, -1, (int)s.cadena.size() + 1, !fin.deMonstruo, fin.carta });
	}
	apropiarPendiente(d);   // (rama classic-probador: por si quedo un robo pendiente)
	s.resolviendo = false;
	s.fakeTrap = {};
	s.mukoUid = 0;
	d.recalcular();
	if (d.ganador >= 0) {
		s.cadena.clear();
		s.disparos.clear();
		s.preg = Pregunta{};
		return;
	}
	seguirTrasCadena(d);
}
// lo que sigue al terminar una cadena (o al cerrarse la ventana del danno): la ventana del danno, los disparos, la ventana
// de la invocacion que hizo un eslabon y, al final, lo pendiente
inline void seguirTrasCadena(Duelo& d)
{
	EstadoEfectos& s = d.ef;
	if (abrirVentanaDanno(d)) return;   // (rama classic-reglas-oficiales: justo despues del danno)
	if (!s.disparos.empty() && s.pendiente != PEND_CALCULO) {
		s.ventana = Ventana{};
		iniciarDisparos(d);
		return;
	}
	if (s.ventanaTras.tipo != V_NINGUNA) {   // (Monster Reborn invoco: ventana de la invocacion especial)
		const Ventana v = s.ventanaTras;
		s.ventanaTras = Ventana{};
		s.ventana = v;
		s.pases = 0;
		ofrecer(d, 1 - v.lado);
		return;
	}
	cerrarVentana(d);
}
// (rama classic-reglas-oficiales) la ventana justo despues del danno (de batalla o de efecto): se abre solo para el que lo
// recibio (primero el del turno) y solo si tiene una carta "cuando recibes danno" que pueda activar (Attack and Receive,
// Numinous Healer, Inferno Tempest). Si no, el momento pasa. true: quedo abierta (pregunta P_RESPUESTA a ese lado)
inline bool abrirVentanaDanno(Duelo& d)
{
	EstadoEfectos& s = d.ef;
	if (!d.efectos) return false;
	if (d.ganador >= 0) {
		s.dannoPend = {};
		s.dannoPendBatalla = {};
		return false;
	}
	if (s.preg.tipo != P_NADA || !s.cadena.empty() || s.resolviendo) return false;
	for (int k = 0; k < 2; k++) {
		const int lado = k == 0 ? d.activo : 1 - d.activo;
		if (!s.dannoPend[(size_t)lado]) continue;
		const int batalla = s.dannoPendBatalla[(size_t)lado];
		s.dannoPend[(size_t)lado] = 0;
		s.dannoPendBatalla[(size_t)lado] = 0;
		const Ventana antes = s.ventana;
		const int batallaAntes = s.dannoVentanaBatalla;
		s.ventana = Ventana{ V_DANNO, lado, -1, 0, {} };
		s.dannoVentanaBatalla = batalla;
		if (activables(d, lado, true).empty()) {
			s.ventana = antes;
			s.dannoVentanaBatalla = batallaAntes;
			continue;
		}
		if (s.pendiente != PEND_DANNO) s.pendienteDanno = s.pendiente;   // (anidada: se queda lo que esperaba la primera)
		s.pendiente = PEND_DANNO;
		s.pases = 0;
		s.pasoDannoSegundo = false;
		s.preg = Pregunta{};
		s.preg.tipo = P_RESPUESTA;
		s.preg.lado = lado;
		return true;
	}
	return false;
}
inline void cerrarVentana(Duelo& d)
{
	EstadoEfectos& s = d.ef;
	s.ventana = Ventana{};
	s.pases = 0;
	s.preg = Pregunta{};
	if (d.ganador >= 0) return;
	const int p = s.pendiente;
	s.pendiente = PEND_NADA;
	if (p == PEND_DANNO) {   // (rama classic-reglas-oficiales: se cerro la ventana del danno: sigue lo que esperaba)
		s.pendiente = s.pendienteDanno;
		s.pendienteDanno = PEND_NADA;
		s.dannoVentanaBatalla = 0;
		seguirTrasCadena(d);
		return;
	}
	if (motorNekoM2(d, p)) return;   // (rama classic-motor2: Neko Mane King pidio la fase final)
	if (motorDiosaTiempo(d, p)) return;   // (Mischief of the Time Goddess: salta a tu proxima batalla)
	if (p == PEND_BATALLA) {
		d.combate();   // (abre la ventana del paso de danno; sin respuestas, sigue con el calculo)
	} else if (p == PEND_CALCULO) {
		d.calculoDanno();
		motorTrasCalculoM2(d);   // (rama classic-motor2: Valkyrie Zweite)
		for (int u : s.destruirTrasCalculo) {   // (Des Counterblow)
			int la = -1, z = -1;
			if (d.porUid(u, &la, &z)) d.alCementerio(la, z);
		}
		s.destruirTrasCalculo.clear();
		for (int u : s.devolverMano) {   // (Begone, Knave!)
			int la = -1, z = -1;
			if (d.porUid(u, &la, &z)) d.sacarMonstruo(la, z, true);
		}
		s.devolverMano.clear();
		d.recalcular();
		if (abrirVentanaDanno(d)) return;   // (rama classic-reglas-oficiales: justo despues del danno de batalla)
		if (!s.disparos.empty() && s.preg.tipo == P_NADA && s.cadena.empty() && s.pendiente == PEND_NADA)
			motorVentana(d, Ventana{ V_DISPARO, d.activo, -1, 0, {} });
	} else if (p == PEND_FIN_TURNO) {
		if ((int)d.l[(size_t)d.activo].mano.size() <= limiteMano(d, d.activo)) d.pasarTurno();
	} else if (p == PEND_ESPERA) {   // (rama classic-motor2: tras la fase de espera, la principal 1)
		d.continuarTurno();
	} else if (p == PEND_FIN_BATALLA) {   // (rama classic-motor2: tras la ventana del final de la batalla)
		d.terminarBatalla();
	}
}
inline void motorVentana(Duelo& d, const Ventana& v, int pendiente)
{
	EstadoEfectos& s = d.ef;
	if (d.ganador >= 0) return;
	s.ventana = v;
	if (pendiente != PEND_NADA) s.pendiente = pendiente;
	s.pases = 0;
	s.pasoDannoSegundo = false;
	if (!s.disparos.empty() && v.tipo != V_PASO_DANNO) {   // (los volteos del paso de danno esperan al calculo)
		iniciarDisparos(d);
		return;
	}
	if (v.tipo == V_DISPARO || v.tipo == V_NINGUNA) {
		cerrarVentana(d);
		return;
	}
	ofrecer(d, v.tipo == V_PASO_DANNO || v.tipo == V_ESPERA ? v.lado : 1 - v.lado);   // (en el paso de danno y la espera, primero el del turno)
}

// ---- pedir una eleccion al resolver: devuelve true si hay que esperar la respuesta (si los candidatos son justo los
// que hay que elegir, se eligen solos)
inline bool preguntar(Duelo& d, Eslabon& e, int lado, const char* texto, const std::vector<Lugar>& cands, int n, bool opcional = false)
{
	if (e.deMonstruo) {   // (Chaos Command Magician no es objetivo de efectos de monstruo: se elige al resolver)
		std::vector<Lugar> c2;
		for (const Lugar& g : cands)
			if (!(g.donde == EN_MONSTRUO && arriba(d.l[(size_t)g.lado].m[(size_t)g.i]) && d.l[(size_t)g.lado].m[(size_t)g.i].id == "chaos_command_magician")) c2.push_back(g);
		if (c2.empty()) return false;
		if (c2.size() != cands.size()) return preguntar(d, e, lado, texto, c2, n, opcional);
	}
	if (cands.empty() || n <= 0) return false;
	if ((int)cands.size() <= n && !opcional) {
		for (const Lugar& g : cands) e.elegidos.push_back(g);
		return false;
	}
	Pregunta p;
	p.tipo = P_ELEGIR;
	p.lado = lado;
	p.carta = e.carta;
	p.texto = texto;
	p.cands = cands;
	p.faltan = std::min(n, (int)cands.size());
	p.opcional = opcional;
	d.ef.preg = p;
	return true;
}

// ---- activar una carta (de la mano, colocada o el efecto de un monstruo)
inline bool activarCarta(Duelo& d, int lado, const Jugada& j, bool comoRespuesta)
{
	const Lugar f = fuenteDe(j, lado);
	if (!motivoNoActivar(d, lado, f, comoRespuesta).empty()) return false;
	const std::string id = cartaEn(d, f);
	const DefCarta& df = *defCarta(id);
	Lado& x = d.l[(size_t)lado];
	if (geminisPendiente(d, f)) {   // (rama classic-torneo-extras) Geminis: invocacion normal sobre el que ya esta en el campo (sin cadena)
		Monstruo& m = x.m[(size_t)f.i];
		x.invocoNormal = true;
		m.geminado = true;
		d.suceso({ S_MODIFICA, lado, f.i, -1, 0, false, id });
		d.recalcular();
		motorVentana(d, Ventana{ V_INVOCACION_NORMAL, lado, f.i, m.uid, id });   // (como una invocacion normal: Torrential Tribute...)
		return true;
	}
	if (f.donde == EN_MANO && d.carta(id) && d.carta(id)->monstruo && (df.desdeMano || df.ignicionMano)) {   // se descarta y su efecto entra en la cadena
		Eslabon e;
		e.carta = id;
		e.lado = lado;
		e.deMonstruo = true;
		e.velocidad = df.desdeMano ? 2 : 1;
		motorPagarMano(d, lado, 1);   // (Chain Energy)
		e.fuente = { lado, EN_CEMENTERIO, -1 };
		d.descartar(lado, f.i);
		d.suceso({ S_ACTIVA_EFECTO, lado, -1, -1, (int)d.ef.cadena.size() + 1, false, id });
		agregarEslabon(d, e);
		return true;
	}
	if (f.donde == EN_MANO && d.carta(id) && d.carta(id)->monstruo && !df.equipoDesdeMano) {   // invocacion por procedimiento: sin cadena
		if (df.nCostes > 0 && !costesValidos(d, lado, df, f, j.costes)) return false;
		motorPagarMano(d, lado, 1);   // (Chain Energy)
		if (df.nCostes > 0) {
			df.pagarCostes(d, lado, j.costes);
		} else if (df.pagarProcedimiento) {
			df.pagarProcedimiento(d, lado);
		}
		int k = f.i;   // (rama classic-torneo-extras: un coste de la mano (Izanagi) movio los indices: la misma carta)
		if (k < 0 || k >= (int)x.mano.size() || x.mano[(size_t)k] != id) k = (int)(std::find(x.mano.begin(), x.mano.end(), id) - x.mano.begin());
		if (k >= (int)x.mano.size()) return false;
		x.mano.erase(x.mano.begin() + k);
		const int dest = df.alCampoRival ? 1 - lado : lado;   // (Lava Golem: al campo del rival)
		const int z = d.invocarEspecial(dest, id, false, lado);
		if (z >= 0 && subtipoDe(d, id) == "espiritu") d.l[(size_t)dest].m[(size_t)z].vuelveFinTurno = true;   // (Yamato-no-Kami: vuelve el turno en que se invoca)
		if (z >= 0) motorVentana(d, Ventana{ V_INVOCACION_ESPECIAL, dest, z, d.l[(size_t)dest].m[(size_t)z].uid, id });
		return true;
	}
	// objetivos
	if ((int)j.objs.size() != df.nObj) return false;
	if (df.nObj > 0) {
		const std::vector<Lugar> cands = objetivosDe(d, lado, df, f);
		for (size_t a = 0; a < j.objs.size(); a++) {
			if (std::find(cands.begin(), cands.end(), j.objs[a]) == cands.end()) return false;
			for (size_t b = 0; b < a; b++)
				if (j.objs[b] == j.objs[a]) return false;
		}
	}
	if (!costesValidos(d, lado, df, f, j.costes)) return false;
	// descartes (coste)
	if ((int)j.descartes.size() != df.descartes) return false;
	for (size_t a = 0; a < j.descartes.size(); a++) {
		const int k = j.descartes[a];
		if (k < 0 || k >= (int)x.mano.size() || (f.donde == EN_MANO && k == f.i)) return false;
		if (!descarteVale(d, id, x.mano[(size_t)k])) return false;   // (Light of Judgment: un LUZ)
		for (size_t b = 0; b < a; b++)
			if (j.descartes[b] == k) return false;
	}
	if (df.unaPorTurno) d.ef.porTurno[(size_t)lado].push_back(id);
	if (df.unaPorDuelo) d.ef.porDuelo[(size_t)lado].push_back(id);
	Eslabon e;
	e.carta = id;
	e.lado = lado;
	e.deMonstruo = f.donde == EN_MONSTRUO;
	e.velocidad = velocidadDe(d, id, e.deMonstruo);
	for (const Lugar& g : j.objs) {
		e.obj.push_back(g);
		e.uidObj.push_back(uidEn(d, g));
		e.idObj.push_back(cartaEn(d, g));
	}
	if (f.donde == EN_MANO) {
		motorPagarMano(d, lado, 1);   // (Chain Energy)
		for (size_t k = 0; k < d.ef.prestadas.size(); k++)   // (Graverobber: usarla cuesta 2000)
			if (d.ef.prestadas[k].lado == lado && d.ef.prestadas[k].id == id && d.ef.prestadas[k].turno == d.turno) {
				d.ef.prestadas.erase(d.ef.prestadas.begin() + (long)k);
				d.danno(lado, 2000);
				break;
			}
	}
	// la carta a su zona, boca arriba
	if (f.donde == EN_MANO) {
		std::vector<int> idx = j.descartes;
		idx.push_back(f.i);
		std::sort(idx.begin(), idx.end(), std::greater<int>());
		std::vector<std::string> fuera;
		for (int k : idx) {
			fuera.push_back(k == f.i ? std::string() : x.mano[(size_t)k]);
			x.mano.erase(x.mano.begin() + k);
		}
		if (subtipoDe(d, id) == "magia_campo") {
			for (int a = 0; a < 2; a++)   // (una sola magia de campo boca arriba en todo el campo)
				if (!d.l[(size_t)a].campo.vacia() && (a == lado || !d.l[(size_t)a].campo.bocaAbajo)) d.mtAlCementerio(a, ZONA_CAMPO);
			x.campo = MagiaTrampa{ id, false };
			x.campo.uid = d.nuevoUid();
			x.campo.turnoColocada = d.turno;
			e.fuente = { lado, EN_CAMPO, ZONA_CAMPO };
			e.uidFuente = x.campo.uid;
		} else {
			const int z = x.libreMT();
			x.mt[(size_t)z] = MagiaTrampa{ id, false };
			x.mt[(size_t)z].uid = d.nuevoUid();
			x.mt[(size_t)z].turnoColocada = d.turno;
			e.fuente = { lado, EN_MT, z };
			e.uidFuente = x.mt[(size_t)z].uid;
		}
		for (const std::string& s : fuera)
			if (!s.empty()) {
				x.cementerio.push_back(s);
				d.suceso({ S_DESCARTA, lado, -1, -1, 0, false, s });
			}
	} else if (f.donde == EN_MT || f.donde == EN_CAMPO) {
		MagiaTrampa& c = *d.mtEn(f);
		if (!c.bocaAbajo) d.ef.usadosTurno.push_back(c.uid);   // (repetible: 1 vez por turno)
		if (c.bocaAbajo && esTrampa(d, c.id) && c.turnoColocada >= d.turno) d.ef.templo[(size_t)lado] = d.turno;   // (Temple of the Kings)
		if (f.donde == EN_CAMPO) {   // (la del rival boca arriba se va)
			const int a = 1 - lado;
			if (!d.l[(size_t)a].campo.vacia() && !d.l[(size_t)a].campo.bocaAbajo) d.mtAlCementerio(a, ZONA_CAMPO);
		}
		c.bocaAbajo = false;
		e.fuente = f;
		e.uidFuente = c.uid;
		std::vector<int> idx = j.descartes;
		std::sort(idx.begin(), idx.end(), std::greater<int>());
		for (int k : idx) d.descartar(lado, k);
	} else {
		Monstruo& m = x.m[(size_t)f.i];
		e.fuente = f;
		e.uidFuente = m.uid;
		d.ef.usadosTurno.push_back(m.uid);
		std::vector<int> idx = j.descartes;
		std::sort(idx.begin(), idx.end(), std::greater<int>());
		for (int k : idx) d.descartar(lado, k);
	}
	if (df.coste) df.coste(d, e);   // (quitar un contador, desterrar...)
	if (df.nCostes > 0 && df.pagarCostes && !j.costes.empty()) df.pagarCostes(d, lado, j.costes);   // (sacrificios / destierros elegidos)
	// el resto del coste: LP
	const int coste = costeLPDe(d, lado, df);   // (Spell Economics)
	if (coste > 0) {
		x.lp -= coste;
		e.valor = 0;
		d.suceso({ S_DANNO, lado, -1, 1, coste });   // (zona2 1: pago de LP, no danno)
	}
	d.suceso({ e.deMonstruo ? S_ACTIVA_EFECTO : S_ACTIVA_MT, lado, e.fuente.donde == EN_CAMPO ? ZONA_CAMPO : e.fuente.i, j.objs.empty() ? -1 : j.objs[0].i,
	           (int)d.ef.cadena.size() + 1, !e.deMonstruo, id });
	agregarEslabon(d, e);
	return true;
}

// ---- J_ACTIVAR / J_PASAR / J_ELEGIR
inline bool motorJugada(Duelo& d, const Jugada& j)
{
	EstadoEfectos& s = d.ef;
	if (d.ganador >= 0) return false;
	if (s.preg.tipo == P_ELEGIR && s.repeticion.hay) {   // (rama classic-reglas-oficiales: la repeticion del ataque)
		if (j.tipo == J_PASAR) return d.responderRepeticion(-1);
		if (j.tipo != J_ELEGIR || j.objetivo < 0 || j.objetivo >= (int)s.preg.cands.size()) return false;
		return d.responderRepeticion(j.objetivo);
	}
	if (s.preg.tipo == P_ELEGIR) {
		if (j.tipo == J_PASAR && s.preg.opcional && !s.cadena.empty()) {   // ("puedes": no elige)
			s.preg = Pregunta{};
			resolverCadena(d);
			return true;
		}
		if (j.tipo != J_ELEGIR || j.objetivo < 0 || j.objetivo >= (int)s.preg.cands.size() || s.cadena.empty()) return false;
		s.cadena.back().elegidos.push_back(s.preg.cands[(size_t)j.objetivo]);
		s.preg.cands.erase(s.preg.cands.begin() + j.objetivo);
		if (--s.preg.faltan > 0 && !s.preg.cands.empty()) return true;
		s.preg = Pregunta{};
		resolverCadena(d);
		return true;
	}
	if (s.preg.tipo == P_RESPUESTA) {
		const int lado = s.preg.lado;
		if (j.tipo == J_PASAR) {
			s.preg = Pregunta{};
			pasar(d, lado);
			return true;
		}
		if (j.tipo != J_ACTIVAR) return false;
		const Pregunta antes = s.preg;
		s.preg = Pregunta{};
		if (!activarCarta(d, lado, j, true)) {
			s.preg = antes;
			return false;
		}
		return true;
	}
	if (j.tipo != J_ACTIVAR || d.ocupado()) return false;
	return activarCarta(d, d.activo, j, false);
}

// ---- continuos: ATK/DEF, ataques prohibidos, fases de espera y final
template <class F> void cadaFuente(const Duelo& d, F f)   // f(ladoFuente, const MagiaTrampa* (o nullptr: monstruo), Lugar, const DefCarta&)
{
	const bool jinzo = jinzoEnCampo(d);
	for (int a = 0; a < 2; a++) {
		const Lado& x = d.l[(size_t)a];
		for (int z = 0; z < ZONAS; z++) {
			const MagiaTrampa& c = x.mt[(size_t)z];
			if (c.vacia() || c.bocaAbajo || (jinzo && esTrampa(d, c.id)) || equipoNegado(d, c) || mtNegadaTurno(d, c, false)) continue;   // (The Emperor's Holiday, Mystic Probe...)
			if (const DefCarta* df = defCarta(c.id)) f(a, &c, Lugar{ a, EN_MT, z }, *df);
		}
		if (!x.campo.vacia() && !x.campo.bocaAbajo && !mtNegadaTurno(d, x.campo, true))   // (World Suppression)
			if (const DefCarta* df = defCarta(x.campo.id)) f(a, &x.campo, Lugar{ a, EN_CAMPO, ZONA_CAMPO }, *df);
		for (int z = 0; z < ZONAS; z++) {
			const Monstruo& m = x.m[(size_t)z];
			if (m.vacia() || m.bocaAbajo || efectoNegado(d, m)) continue;   // (Skill Drain...)
			if (const DefCarta* df = defCarta(m.id)) f(a, nullptr, Lugar{ a, EN_MONSTRUO, z }, *df);
		}
	}
}
inline void motorGaap(Duelo& d);
inline void motorRecalcular(Duelo& d)
{
	for (int a = 0; a < 2; a++)
		for (int z = 0; z < ZONAS; z++) {
			Monstruo& m = d.l[(size_t)a].m[(size_t)z];
			if (m.vacia()) continue;
			if (m.bocaAbajo) m.geminado = false;   // (rama classic-torneo-extras: un Geminis boca abajo vuelve a ser normal)
			int pa = d.atk(m.id) + m.atkTurno + m.atkPerm, pd = d.def(m.id) + m.defTurno + m.defPerm;
			if (!m.bocaAbajo && !efectoNegado(d, m))   // (Skill Drain...)
				if (const DefCarta* dp = defCarta(m.id))
					if (dp->atkPropio) {
						const int extra = dp->atkPropio(d, a, z);
						pa += extra;
						pd += extra;
					}
			if (const DefCarta* dm = m.contadores > 0 && !m.bocaAbajo ? defCarta(m.id) : nullptr) pa += dm->atkPorContador * m.contadores;
			cadaFuente(d, [&](int lf, const MagiaTrampa* c, const Lugar&, const DefCarta& df) {
				if (c && d.ef.cristalTurno == d.turno && subtipoDe(d, c->id) == "magia_equipo") return;   // (Armored Glass)
				if (df.modAtk) pa += df.modAtk(d, lf, c, a, z);
				if (df.modDef) pd += df.modDef(d, lf, c, a, z);
			});
			if (d.ef.reversa == d.turno && !jinzoEnCampo(d)) {   // (Reverse Trap: las sumas restan y las restas suman)
				pa = 2 * d.atk(m.id) - pa;
				pd = 2 * d.def(m.id) - pd;
			}
			m.atkEf = std::max(0, pa);
			m.defEf = std::max(0, pd);
		}
	motorGaap(d);   // (Gaap the Divine Soldier: todos en ataque)
}
// los Toons (subtipo toon de cartas_classic.txt): no atacan el turno en que llegan; los de "pagar 500" necesitan LP
inline bool esToon(const Duelo& d, const std::string& id) { return subtipoDe(d, id) == "toon"; }
inline bool pagaToon(const std::string& id)
{
	return id == "blue_eyes_toon_dragon" || id == "manga_ryu_ran" || id == "toon_mermaid" || id == "toon_summoned_skull";
}
inline bool motorPerfora(const std::string& id)
{
	const DefCarta* df = defCarta(id);
	return df && df->perfora;
}
inline bool motorAtaqueDirecto(const Duelo& d, int lado, int z)
{
	const Monstruo& m = d.l[(size_t)lado].m[(size_t)z];
	const std::string mid = efectoNegado(d, m) ? std::string() : m.id;   // (Skill Drain: sin sus efectos)
	if (mid == "prinzessin" && monstruoArriba(d, lado, "pumpkin_carriage")) return true;
	if (mid == "leghul" || mid == "ooguchi" || mid == "nightmare_horse" || mid == "mucus_yolk" || mid == "raging_flame_sprite" ||
	    mid == "servant_of_catabolism" || mid == "inaba_white_rabbit")
		return true;
	if (mid == "alligator_s_sword_dragon" || mid == "reaper_on_the_nightmare") {   // (rama classic-probador)
		bool alguno = false, todos = true;
		for (const Monstruo& o : d.l[(size_t)(1 - lado)].m) {
			if (!arriba(o)) continue;
			alguno = true;
			if (mid == "alligator_s_sword_dragon") {
				const std::string at = atributoDe(d, o);
				todos &= at == "TIERRA" || at == "AGUA" || at == "FUEGO";
			} else {
				todos &= o.defensa;
			}
		}
		if (alguno && todos && (mid == "alligator_s_sword_dragon" || contarMT(d, 1 - lado) == 0)) return true;
	}
	if (false)   // (rama classic-probador: Servant of Catabolism estaba en la lista "por reglas" sin la regla)
		return true;
	if (d.ef.finAbsoluto[(size_t)lado] == d.turno) return true;   // (Absolute End)
	if (mid == "rocket_jumper" && contarMT(d, 1 - lado) == 0) {   // (solo monstruos en defensa en el campo del rival)
		bool todos = true;
		for (const Monstruo& o : d.l[(size_t)(1 - lado)].m)
			if (!o.vacia() && !o.defensa) todos = false;
		if (todos) return true;
	}
	for (const Lado& x : d.l)   // (Shooting Star Bow - Ceal)
		for (const MagiaTrampa& c : x.mt)
			if (!c.vacia() && !c.bocaAbajo && (c.id == "shooting_star_bow_ceal" || c.id == "opti_camouflage_armor") && c.eqUid == m.uid && m.uid > 0) return true;
	{   // (rama classic-torneo-extras) dos o mas Command Knight y nada mas: ninguno se puede atacar, el ataque es directo
		const Lado& y = d.l[(size_t)(1 - lado)];
		bool todos = y.monstruos() > 1;
		for (const Monstruo& o : y.m)
			if (!o.vacia() && !(arriba(o) && o.id == "command_knight" && !efectoNegado(d, o))) todos = false;
		if (todos) return true;
	}
	{   // (Guardian Kay'est no se puede atacar, pero no impide el ataque directo)
		bool solo = d.l[(size_t)(1 - lado)].monstruos() > 0;
		for (const Monstruo& o : d.l[(size_t)(1 - lado)].m)
			if (!o.vacia() && !(arriba(o) && o.id == "guardian_kay_est") && !esMensajeEspiritu(o.id)) solo = false;
		if (solo) return true;
	}
	if (m.directoTurno || mid == "mystic_lamp" || mid == "jinzo_7" || mid == "queen_s_double" || mid == "rainbow_flower" || mid == "jinzo_returner") return true;
	if (mid == "shadowslayer" || mid == "black_tyranno") {   // (todos los del rival en defensa; Black Tyranno: y sin magias/trampas)
		bool todos = true;
		for (const Monstruo& o : d.l[(size_t)(1 - lado)].m)
			if (!o.vacia() && !o.defensa) todos = false;
		if (todos && (mid == "shadowslayer" || contarMT(d, 1 - lado) == 0)) return true;
	}   // (Gear Golem pago este turno; Mystic Lamp siempre)
	if (mid == "amphibious_bugroth_mk_3") {
		bool hayCampo = false;
		for (const Lado& x : d.l) {
			if (!x.campo.vacia() && !x.campo.bocaAbajo) hayCampo = true;
			if (!x.campo.vacia() && !x.campo.bocaAbajo && (x.campo.id == "umi" || x.campo.id == "a_legendary_ocean")) return true;
		}
		if (!hayCampo)   // Maiden of the Aqua: sin magia de campo activa, el campo cuenta como Umi
			for (const Lado& x : d.l)
				for (const Monstruo& o : x.m)
					if (arriba(o) && o.id == "maiden_of_the_aqua") return true;
	}
	if (mid == "drillago") {
		const Lado& y = d.l[(size_t)(1 - lado)];
		bool vale = contarMT(d, 1 - lado) == 0;
		for (const Monstruo& o : y.m)
			if (!o.vacia() && (o.bocaAbajo || d.atkM(o) < 1600)) vale = false;
		if (vale) return true;
	}
	if (m.vacia() || !esToon(d, m.id) || !d.l[(size_t)lado].tieneBocaArriba("toon_world")) return false;
	for (const Monstruo& o : d.l[(size_t)(1 - lado)].m)
		if (arriba(o) && esToon(d, o.id)) return false;
	return true;
}
// Zombyra the Dark no ataca directo
inline bool motorPuedeDirecto(const Duelo& d, int lado, int z) { return d.l[(size_t)lado].m[(size_t)z].id != "zombyra_the_dark"; }
// el control que no cambia: Element Valkyrie con un AGUA en el campo; Horus LV4
inline bool hayAtributoArriba(const Duelo& d, const char* atr);
inline bool motorPuedeCambiarControl(const Duelo& d, const Monstruo& m)
{
	if (m.id == "horus_the_black_flame_dragon_lv4" || m.id == "mataza_the_zapper") return false;
	if ((m.id == "element_soldier" || m.id == "element_magician") && hayAtributoArriba(d, "AGUA")) return false;
	if (m.id == "element_valkyrie")
		for (const Lado& x : d.l)
			for (const Monstruo& o : x.m)
				if (arriba(o) && d.carta(o.id) && d.carta(o.id)->atributo == "AGUA") return false;
	return true;
}
inline void motorDeclaraAtaque(Duelo& d, int lado, int z)
{
	const Monstruo& m = d.l[(size_t)lado].m[(size_t)z];
	if (d.l[0].tieneBocaArriba("toll") || d.l[1].tieneBocaArriba("toll")) {   // (Toll: 500 por declarar el ataque)
		d.l[(size_t)lado].lp -= 500;
		d.suceso({ S_DANNO, lado, -1, 1, 500 });
	}
	if (m.id == "dark_elf") {
		d.l[(size_t)lado].lp -= 1000;
		d.suceso({ S_DANNO, lado, -1, 1, 1000 });
	}
	Monstruo& mm = d.l[(size_t)lado].m[(size_t)z];
	if (mm.id == "diabound_kernel") mm.atkPerm += 600;
	// (Jirai Gumo: la moneda cantada, motorSucesoAR)
	if ((mm.id == "mataza_the_zapper" || mm.id == "hayabusa_knight" || mm.id == "twinheaded_beast" || mm.id == "master_monk" || tryceEquipado(d, mm)) && std::find(d.ef.usadosTurno.begin(), d.ef.usadosTurno.end(), mm.uid) == d.ef.usadosTurno.end()) {
		d.ef.usadosTurno.push_back(mm.uid);   // (Mataza the Zapper: un segundo ataque)
		mm.ataco = false;
	}
	if (d.l[(size_t)(1 - lado)].tieneBocaArriba("gravekeeper_s_servant") && !d.l[(size_t)lado].mazo.empty()) {   // (Gravekeeper's Servant)
		const std::string id = d.l[(size_t)lado].mazo.back();
		d.l[(size_t)lado].mazo.pop_back();
		d.aCementerio(lado, id);
	}
	for (const MagiaTrampa& k : d.l[(size_t)(1 - lado)].mt)   // (Mirror Wall)
		if (!k.vacia() && !k.bocaAbajo && k.id == "mirror_wall" && !jinzoEnCampo(d)) d.ef.espejo.push_back(mm.uid);
	if (mm.id == "panther_warrior" || mm.id == "insect_queen") {   // (sacrifica otro monstruo para declarar el ataque)
		int peor = -1;
		float vm = 1e9f;
		for (int k = 0; k < ZONAS; k++) {
			const Monstruo& o = d.l[(size_t)lado].m[(size_t)k];
			if (o.vacia() || k == z) continue;
			if (valorMonstruo(d, o) < vm) vm = valorMonstruo(d, o), peor = k;
		}
		if (peor >= 0) d.alCementerio(lado, peor);
	}
	if ((mm.id == "asura_priest" || mm.id == "mermaid_knight" || mm.id == "ultimate_tyranno" || mm.id == "berserk_dragon" || mm.id == "armed_samurai_ben_kei") &&
	    mm.contadores == 0) {   // (el primer ataque del turno)
		int extra = 0;
		if (mm.id == "armed_samurai_ben_kei")
			for (const MagiaTrampa& k : d.l[(size_t)lado].mt) extra += !k.vacia() && !k.bocaAbajo && k.eqUid == mm.uid;
		else if (mm.id == "asura_priest" || mm.id == "ultimate_tyranno" || mm.id == "berserk_dragon") extra = d.l[(size_t)(1 - lado)].monstruos() - 1;
		else
			for (const Lado& x : d.l)
				if (!x.campo.vacia() && !x.campo.bocaAbajo && (x.campo.id == "umi" || x.campo.id == "a_legendary_ocean")) extra = 1;
		if (extra > 0) {
			mm.ataco = false;
			mm.ataquesExtra = extra - 1;
			mm.contadores = 1;
		}
	}
	if (!pagaToon(m.id)) return;
	d.l[(size_t)lado].lp -= 500;
	d.suceso({ S_DANNO, lado, -1, 1, 500 });   // (pago)
}
inline void motorDannoBatalla(Duelo& d, int lado, int z, const Monstruo& m)
{
	const std::string mid = efectoNegado(d, d.l[(size_t)lado].m[(size_t)z]) ? std::string() : m.id;   // (Skill Drain)
	if (mid == "silent_swordsman_lv5" && d.ultimoDefensor.empty() && d.l[(size_t)lado].m[(size_t)z].uid == m.uid) d.l[(size_t)lado].m[(size_t)z].contadores = 1;
	if ((d.l[0].tieneBocaArriba("begone_knave") || d.l[1].tieneBocaArriba("begone_knave")) && !jinzoEnCampo(d))
		d.ef.devolverMano.push_back(m.uid);   // (Begone, Knave!: vuelve a la mano tras el calculo)
	if (razaEs(d, m.id, "Bestia") && d.l[(size_t)lado].tieneBocaArriba("poison_fangs") && !jinzoEnCampo(d)) d.danno(1 - lado, 500);   // (Poison Fangs)
	for (const auto& b : d.ef.bandidos)   // (The Secret of the Bandit)
		if (b.first == m.uid && b.second == d.turno && !d.l[(size_t)(1 - lado)].mano.empty()) {
			d.descartar(1 - lado, d.ef.azar.hasta((int)d.l[(size_t)(1 - lado)].mano.size()));
			break;
		}
	if (d.ultimoDefensor.empty() && mid == "raging_flame_sprite" && d.l[(size_t)lado].m[(size_t)z].uid == m.uid) d.l[(size_t)lado].m[(size_t)z].atkPerm += 1000;   // (Raging Flame Sprite)
	if (d.ultimoDefensor.empty() && d.ef.sebek[(size_t)lado] == d.turno) d.ganarLP(lado, d.ef.ultimoDannoBatalla);   // (Sebek's Blessing)
	if (d.l[(size_t)lado].tieneBocaArriba("robbin_goblin") && !jinzoEnCampo(d) && !d.l[(size_t)(1 - lado)].mano.empty())   // (Robbin' Goblin)
		d.descartar(1 - lado, d.ef.azar.hasta((int)d.l[(size_t)(1 - lado)].mano.size()));
	if (d.ultimoDefensor.empty() && !jinzoEnCampo(d) && (d.l[0].tieneBocaArriba("des_counterblow") || d.l[1].tieneBocaArriba("des_counterblow")))
		d.ef.destruirTrasCalculo.push_back(m.uid);   // (Des Counterblow: danno directo)
	for (const MagiaTrampa& k : d.l[(size_t)lado].mt)   // (Cestus of Dagla: ganas el danno)
		if (!k.vacia() && !k.bocaAbajo && k.id == "cestus_of_dagla" && k.eqUid == m.uid) d.ganarLP(lado, d.ef.ultimoDannoBatalla);
	for (int k = 0; k < ZONAS; k++) {   // (Burning / Freezing Beast, Armor Breaker equipados)
		const MagiaTrampa& u = d.l[(size_t)lado].mt[(size_t)k];
		if (!u.vacia() && !u.bocaAbajo && u.eqUid == m.uid && (u.id == "burning_beast" || u.id == "freezing_beast" || u.id == "armor_breaker")) {
			dispararMonstruo(d, lado, { lado, EN_MT, k }, u.id, u.uid);
			d.ef.disparos.back().efecto = 2;
		}
	}
	const DefCarta* df = defCarta(m.id);
	if (df && df->disparo == D_DANNO_BATALLA && df->resolver && !efectoNegado(d, d.l[(size_t)lado].m[(size_t)z])) {
		Eslabon e;
		e.valor = d.ef.ultimoDannoBatalla;
		e.carta = m.id;
		e.lado = lado;
		e.fuente = { lado, EN_MONSTRUO, z };
		e.uidFuente = m.uid;
		e.deMonstruo = true;
		d.ef.disparos.push_back(e);
	}
	if (mid == "goblin_zombie" && d.l[(size_t)lado].m[(size_t)z].uid == m.uid) {   // (rama classic-torneo-extras: Goblin Zombie)
		dispararMonstruo(d, lado, { lado, EN_MONSTRUO, z }, m.id, m.uid);
		if (!d.ef.disparos.empty() && d.ef.disparos.back().carta == m.id) d.ef.disparos.back().efecto = 3;
	}
	motorDannoBatallaM2(d, lado, z, m);   // (rama classic-motor2: Reaper on the Nightmare, Zombie Tiger...)
}
inline bool motorPuedeAtacar(const Duelo& d, int lado, int z)
{
	const Monstruo& m = d.l[(size_t)lado].m[(size_t)z];
	const std::string mid = efectoNegado(d, m) ? std::string() : m.id;   // (Skill Drain: sin sus efectos)
	if (d.ef.sinAtaqueTurno[(size_t)lado] == d.turno) return false;   // (Threatening Roar, Teva)
	if (!motorPuedeAtacarM2(d, lado, z)) return false;   // (rama classic-motor2: Thousand-Eyes Restrict, The Unhappy Girl...)
	if ((d.l[0].tieneBocaArriba("toll") || d.l[1].tieneBocaArriba("toll")) && d.l[(size_t)lado].lp <= 500) return false;   // (Toll)
	if (esToon(d, m.id) && (m.llegoEsteTurno || (pagaToon(m.id) && d.l[(size_t)lado].lp <= 500))) return false;
	if (mid == "dark_elf" && d.l[(size_t)lado].lp <= 1000) return false;
	if ((mid == "panther_warrior" || mid == "insect_queen") && d.l[(size_t)lado].monstruos() < 2) return false;
	if (m.sinAtacarHasta >= d.turno) return false;   // (Electric Lizard, Harpie Lady 3)
	if (mid == "cave_dragon" && contarRaza(d, lado, "Dragón", m.uid) == 0) return false;   // (Cave Dragon: con otro Dragon)
	for (int a = 0; a < 2; a++)   // (D.D. Borderline: sin magias en el cementerio de su controlador, no hay batalla)
		if (d.l[(size_t)a].tieneBocaArriba("d_d_borderline")) {
			bool magia = false;
			for (const std::string& id : d.l[(size_t)a].cementerio) magia |= esMagia(d, id);
			if (!magia) return false;
		}
	if (mid != "ultimate_tyranno")   // (Ultimate Tyranno: mientras pueda atacar, los demas no)
		for (const Monstruo& o : d.l[(size_t)lado].m)
			if (arriba(o) && o.id == "ultimate_tyranno" && !o.defensa && !o.ataco) return false;
	if (m.llegoEsteTurno && (mid == "andro_sphinx" || mid == "armor_exe")) return false;
	if (m.llegoEsteTurno)
		for (const Monstruo& o : d.l[(size_t)(1 - lado)].m)
			if (arriba(o) && o.id == "big_tusked_mammoth") return false;
	bool puede = true;
	cadaFuente(d, [&](int lf, const MagiaTrampa* c, const Lugar&, const DefCarta& df) {
		if (puede && df.impideAtaque && df.impideAtaque(d, lf, c, lado, z)) puede = false;
	});
	return puede;
}
inline void motorFaseEspera(Duelo& d)
{
	d.ef.usadosTurno.clear();
	if (d.ef.sinEspera[(size_t)d.activo] == d.turno) return;   // (Solomon's Lawbook: sin fase de espera)
	motorEsperaM2(d);   // (rama classic-motor2: Diabound Kernel vuelve)
	if (d.ef.revivalJam[(size_t)d.activo] > 0) {   // Revival Jam pago: vuelve en defensa
		d.ef.revivalJam[(size_t)d.activo] = 0;
		Lado& x = d.l[(size_t)d.activo];
		auto it = std::find(x.cementerio.begin(), x.cementerio.end(), "revival_jam");
		if (it != x.cementerio.end() && x.libre() >= 0) {
			x.cementerio.erase(it);
			d.invocarEspecial(d.activo, "revival_jam", true);
		}
	}
	d.ef.manticoras.clear();
	for (int a = 0; a < 2; a++)   // (Final Countdown)
		if (d.ef.cuentaFinal[(size_t)a] >= 0 && d.turno > d.ef.cuentaFinal[(size_t)a]) d.terminar(a);
	if (d.ef.fenix[(size_t)d.activo] > 0) {   // Sacred Phoenix of Nephthys: vuelve y destruye las magias/trampas
		d.ef.fenix[(size_t)d.activo] = 0;
		Lado& x = d.l[(size_t)d.activo];
		auto it = std::find(x.cementerio.begin(), x.cementerio.end(), "sacred_phoenix_of_nephthys");
		if (it != x.cementerio.end() && x.libre() >= 0 && !anubisEnCampo(d)) {
			x.cementerio.erase(it);
			d.invocarEspecial(d.activo, "sacred_phoenix_of_nephthys", false);
			destruirMTs(d, -1, 0);
		}
	}
	if (d.ef.vampiroLord[(size_t)d.activo] > 0) {   // Vampire Lord: vuelve
		d.ef.vampiroLord[(size_t)d.activo] = 0;
		Lado& x = d.l[(size_t)d.activo];
		auto it = std::find(x.cementerio.begin(), x.cementerio.end(), "vampire_lord");
		if (it != x.cementerio.end() && x.libre() >= 0 && !anubisEnCampo(d)) {
			x.cementerio.erase(it);
			d.invocarEspecial(d.activo, "vampire_lord", false);
		}
	}
	if (d.ef.maliceDoll[(size_t)d.activo] > 0) {   // Malice Doll of Demise: vuelve
		d.ef.maliceDoll[(size_t)d.activo] = 0;
		Lado& x = d.l[(size_t)d.activo];
		auto it = std::find(x.cementerio.begin(), x.cementerio.end(), "malice_doll_of_demise");
		if (it != x.cementerio.end() && x.libre() >= 0 && !anubisEnCampo(d)) {
			x.cementerio.erase(it);
			d.invocarEspecial(d.activo, "malice_doll_of_demise", false);
		}
	}
	{   // Darklord Marie en tu cementerio: +200 LP en tu fase de espera
		const Lado& x = d.l[(size_t)d.activo];
		if (std::find(x.cementerio.begin(), x.cementerio.end(), "darklord_marie") != x.cementerio.end() && !anubisEnCampo(d)) d.ganarLP(d.activo, 200);
	}
	{   // Sinister Serpent: en tu fase de espera vuelve del cementerio a la mano (atajo: siempre que este)
		Lado& x = d.l[(size_t)d.activo];
		auto it = std::find(x.cementerio.begin(), x.cementerio.end(), "sinister_serpent");
		if (it != x.cementerio.end() && !anubisEnCampo(d)) {
			x.cementerio.erase(it);
			x.mano.push_back("sinister_serpent");
			d.suceso({ S_A_LA_MANO, d.activo, -1, -1, 2, false, "sinister_serpent" });
		}
	}
	std::vector<std::pair<int, Lugar>> lst;   // (las fuentes pueden irse del campo mientras se aplican)
	cadaFuente(d, [&](int lf, const MagiaTrampa*, const Lugar& g, const DefCarta& df) {
		if (df.espera) lst.push_back({ lf, g });
	});
	for (auto& p : lst) {
		const std::string id = cartaEn(d, p.second);
		const DefCarta* df = defCarta(id);
		if (df && df->espera && d.ganador < 0) df->espera(d, p.first, p.second);
	}
	d.recalcular();
}
inline void motorFinTurno(Duelo& d)
{
	// el control prestado vuelve (Change of Heart)
	for (int a = 0; a < 2; a++)
		for (int z = 0; z < ZONAS; z++) {
			Monstruo& m = d.l[(size_t)a].m[(size_t)z];
			if (m.vacia() || !m.hastaFinTurno) continue;
			if (d.cambiarControl(a, z) < 0) d.alCementerio(a, z);   // (sin zona libre: al cementerio)
		}
	std::vector<std::pair<int, Lugar>> lst;
	cadaFuente(d, [&](int lf, const MagiaTrampa*, const Lugar& g, const DefCarta& df) {
		if (df.finTurno) lst.push_back({ lf, g });
	});
	for (auto& p : lst) {
		const DefCarta* df = defCarta(cartaEn(d, p.second));
		if (df && df->finTurno && d.ganador < 0) df->finTurno(d, p.first, p.second);
	}
	// los marcados para la fase final (Limiter Removal: destruir; Return from the Different Dimension: desterrar)
	for (int u : d.ef.destruirFin) {
		int la = -1, z = -1;
		if (d.porUid(u, &la, &z)) d.alCementerio(la, z);
	}
	for (int u : d.ef.desterrarFin) {
		int la = -1, z = -1;
		if (d.porUid(u, &la, &z)) d.sacarMonstruo(la, z, false);
	}
	d.ef.destruirFin.clear();
	d.ef.desterrarFin.clear();
	for (int u : d.ef.alExtraFin) {   // (Magical Scientist)
		int la = -1, z = -1;
		if (d.porUid(u, &la, &z)) d.sacarMonstruo(la, z, true);
	}
	d.ef.alExtraFin.clear();
	// D.D. Survivor desterrado boca arriba de su campo este turno: vuelve. Twin-Headed Behemoth destruido este turno:
	// vuelve con 1000/1000 (1 por duelo; atajo: siempre que pueda)
	for (int a = 0; a < 2 && d.ganador < 0; a++) {
		Lado& x = d.l[(size_t)a];
		auto& dd = d.ef.desterradosCampo[(size_t)a];
		for (const char* vuelve : { "d_d_survivor", "d_d_scout_plane" })   // (D.D. Scout Plane: atajo, solo desde el campo)
			if (std::find(dd.begin(), dd.end(), vuelve) != dd.end() && x.libre() >= 0) {
				auto it = std::find(x.desterrados.begin(), x.desterrados.end(), vuelve);
				if (it != x.desterrados.end()) {
					x.desterrados.erase(it);
					d.invocarEspecial(a, vuelve, false);
				}
			}
		auto& dc = d.ef.destruidosCampo[(size_t)a];
		if (!d.ef.behemothUsado[(size_t)a] && std::find(dc.begin(), dc.end(), "twin_headed_behemoth") != dc.end() && x.libre() >= 0 &&
		    std::find(x.cementerio.begin(), x.cementerio.end(), "twin_headed_behemoth") != x.cementerio.end()) {
			dispararMonstruo(d, a, { a, EN_CEMENTERIO, -1 }, "twin_headed_behemoth", 0);   // (opcional: pregunta)
			if (!d.ef.disparos.empty()) d.ef.disparos.back().efecto = 12;
		}
	}
	for (int a = 0; a < 2; a++)   // (Fox Fire: destruido en batalla este turno, vuelve)
		for (; d.ef.zorros[(size_t)a] > 0; d.ef.zorros[(size_t)a]--) {
			Lado& x = d.l[(size_t)a];
			auto it = std::find(x.cementerio.begin(), x.cementerio.end(), "fox_fire");
			if (it == x.cementerio.end() || x.libre() < 0) continue;
			x.cementerio.erase(it);
			d.invocarEspecial(a, "fox_fire", false);
		}
	for (int u : d.ef.lucharon) {   // (After the Struggle)
		int la = -1, z = -1;
		if (d.porUid(u, &la, &z)) d.alCementerio(la, z);
	}
	d.ef.lucharon.clear();
	for (const auto& p : d.ef.prestadas) {   // (Graverobber: la que no se uso vuelve al cementerio del rival)
		if (p.turno != d.turno) continue;
		auto& mano = d.l[(size_t)p.lado].mano;
		auto it = std::find(mano.begin(), mano.end(), p.id);
		if (it == mano.end()) continue;
		mano.erase(it);
		d.l[(size_t)(1 - p.lado)].cementerio.push_back(p.id);
	}
	d.ef.prestadas.clear();
	for (int a = 0; a < 2; a++)   // (Ride of the Valkyries: tus monstruos al mazo)
		if (d.ef.rideFin[(size_t)a] == d.turno) {
			d.ef.rideFin[(size_t)a] = -1;
			for (int z = 0; z < ZONAS; z++) {
				Monstruo& m = d.l[(size_t)a].m[(size_t)z];
				if (m.vacia()) continue;
				const int duenno = m.duenno >= 0 ? m.duenno : a;
				const std::string id = m.id;
				const bool token = m.token;
				m = Monstruo{};
				if (!token) d.l[(size_t)duenno].mazo.push_back(id);
				d.suceso({ S_A_LA_MANO, a, z, -1, 5, false, id });
			}
			barajar(d.l[(size_t)a].mazo, d.ef.azar);
		}
	for (const auto& v : d.ef.vuelvenFin) {   // (Strike Ninja)
		Lado& x = d.l[(size_t)v.first];
		auto it = std::find(x.desterrados.begin(), x.desterrados.end(), v.second);
		if (it == x.desterrados.end() || x.libre() < 0) continue;
		x.desterrados.erase(it);
		d.invocarEspecial(v.first, v.second, false);
	}
	d.ef.vuelvenFin.clear();
	for (size_t k = 0; k < d.ef.escorpion.size();) {   // (Steel Scorpion)
		if (d.turno < d.ef.escorpion[k].second) {
			k++;
			continue;
		}
		int la = -1, z = -1;
		if (d.porUid(d.ef.escorpion[k].first, &la, &z)) d.alCementerio(la, z);
		d.ef.escorpion.erase(d.ef.escorpion.begin() + (long)k);
	}
	for (int a : d.ef.manticoras)   // (Manticore of Darkness: se dispara)
		dispararMonstruo(d, a, { a, EN_CEMENTERIO, -1 }, "manticore_of_darkness", 0);
	d.ef.manticoras.clear();
	d.ef.desterradosCampo = {};
	d.ef.destruidosCampo = {};
	// los Dioses Egipcios invocados de forma especial se van al cementerio
	for (int a = 0; a < 2; a++)
		for (int z = 0; z < ZONAS; z++) {
			const Monstruo& m = d.l[(size_t)a].m[(size_t)z];
			if (!m.vacia() && m.especial && Duelo::divina(d.carta(m.id))) d.alCementerio(a, z);
		}
	// los Spirit invocados o volteados este turno vuelven a la mano
	for (int a = 0; a < 2; a++)
		for (int z = 0; z < ZONAS; z++) {
			Monstruo& m = d.l[(size_t)a].m[(size_t)z];
			if (m.vacia() || !m.vuelveFinTurno || maquinaEspiritu(d)) continue;   // (Spiritual Energy Settle Machine)
			m.vuelveFinTurno = false;
			if (m.bocaAbajo) continue;
			if (const int zi = izanagiDe(d, a); zi >= 0) {   // (rama classic-torneo-extras) Izanagi: su controlador decide si vuelve
				pedirDisparo(d, a, { a, EN_MONSTRUO, zi }, EF_IZANAGI, m.uid);
				continue;
			}
			d.sacarMonstruo(a, z, true);
		}
	motorFinTurnoM2(d);   // (rama classic-motor2: Dark Necrofear)
	for (Lado& x : d.l)
		for (Monstruo& m : x.m) m.atkTurno = m.defTurno = 0, m.vuelveFinTurno = false;
	d.recalcular();
}
inline void motorSaleMT(Duelo& d, int lado, const MagiaTrampa& c)
{
	const DefCarta* df = defCarta(c.id);
	if (df && df->alSalir && !c.bocaAbajo) df->alSalir(d, lado, c);
	for (int a = 0; a < 2; a++)   // (Mask of Dispel)
		for (int z = 0; z < ZONAS; z++) {
			const MagiaTrampa& k = d.l[(size_t)a].mt[(size_t)z];
			if (!k.vacia() && !k.bocaAbajo && k.id == "mask_of_dispel" && k.contadores == c.uid && c.uid > 0) d.mtAlCementerio(a, z);
		}
}
// los sucesos que disparan efectos de monstruos (tanda 5: volteo, al cementerio...)
inline void dispararMonstruo(Duelo& d, int lado, const Lugar& fuente, const std::string& id, int uid)
{
	if (fuente.donde == EN_MONSTRUO && fuente.i >= 0 && fuente.i < ZONAS && efectoNegado(d, d.l[(size_t)fuente.lado].m[(size_t)fuente.i])) return;   // (Skill Drain...)
	Eslabon e;
	e.carta = id;
	e.lado = lado;
	e.fuente = fuente;
	e.uidFuente = uid;
	e.deMonstruo = true;
	e.velocidad = 1;
	e.efecto = 1;   // (disparado, no activado a mano)
	d.ef.disparos.push_back(e);
}
// Exodia: las 5 piezas en la mano ganan el duelo
inline void mirarExodia(Duelo& d, int lado)
{
	static const char* const PIEZAS[] = { "exodia_the_forbidden_one", "left_arm_of_the_forbidden_one", "right_arm_of_the_forbidden_one",
		                                  "left_leg_of_the_forbidden_one", "right_leg_of_the_forbidden_one" };
	const auto& mano = d.l[(size_t)lado].mano;
	for (const char* p : PIEZAS)
		if (std::find(mano.begin(), mano.end(), p) == mano.end()) return;
	d.terminar(lado);
}
