		c.condicion = [](const Duelo& d, int lado, const Lugar&) {
			for (const std::string& id : d.ef.destruidosBatalla[(size_t)lado])
				if (std::find(d.l[(size_t)lado].cementerio.begin(), d.l[(size_t)lado].cementerio.end(), id) != d.l[(size_t)lado].cementerio.end()) return true;
			return false;
		};
		c.coste = [](Duelo& d, Eslabon& e) {
			int la = -1, z = -1;
			if (d.porUid(e.uidFuente, &la, &z)) d.alCementerio(la, z);
		};
		c.resolver = [](Duelo& d, Eslabon& e) {
			Lado& x = d.l[(size_t)e.lado];
			if (e.paso == 0) {
				e.paso = 1;
				std::vector<Lugar> cands;
				std::vector<std::string> vistos;
				for (int i = 0; i < (int)x.cementerio.size(); i++) {
					const std::string& id = x.cementerio[(size_t)i];
					const auto& db = d.ef.destruidosBatalla[(size_t)e.lado];
					if (std::find(db.begin(), db.end(), id) == db.end() || std::find(vistos.begin(), vistos.end(), id) != vistos.end()) continue;
					vistos.push_back(id);
					cands.push_back({ e.lado, EN_CEMENTERIO, i });
				}
				if (preguntar(d, e, e.lado, "ef.elegir.traer", cands, 1)) return;
			}
			for (const Lugar& g : e.elegidos) {
				if (g.i < 0 || g.i >= (int)x.cementerio.size()) continue;
				const std::string id = x.cementerio[(size_t)g.i];
				x.cementerio.erase(x.cementerio.begin() + g.i);
				x.mano.push_back(id);
				d.suceso({ S_A_LA_MANO, e.lado, -1, -1, 2, false, id });
			}
		};
		c.valor = [](const Duelo&, int, const std::vector<Lugar>&) { return 300.0f; };
