			static const char* const ATR[] = { "LUZ", "OSCURIDAD", "TIERRA", "AGUA", "FUEGO", "VIENTO" };
			float neto[6] = {};
			for (int k = 0; k < 6; k++)
				for (int a = 0; a < 2; a++)
					for (const Monstruo& m : d.l[(size_t)a].m)
						if (arriba(m) && atributoDe(d, m) == ATR[k]) neto[k] += (a == e.lado ? -1.0f : 1.0f) * valorMonstruo(d, m);
